const MANIFEST = {
  "type": "Cards.StaggeredElevation",
  "description": "Services cards with staggered elevation creating a staircase depth effect",
  "editorElement": {
    "selector": ".staggered-elevation-cards",
    "displayName": "Staggered Elevation Cards",
    "archetype": "container",
    "data": {
      "sectionTitle": {
        "dataType": "text",
        "displayName": "Section Title",
        "defaultValue": "Our Services",
        "group": "Content"
      },
      "sectionSubtitle": {
        "dataType": "text",
        "displayName": "Section Subtitle",
        "defaultValue": "Comprehensive solutions tailored to your needs",
        "group": "Content"
      },
      "card1Title": {
        "dataType": "text",
        "displayName": "Card 1 Title",
        "defaultValue": "Strategy",
        "group": "Card 1"
      },
      "card1Description": {
        "dataType": "text",
        "displayName": "Card 1 Description",
        "defaultValue": "Data-driven strategies that align with your business goals and market opportunities.",
        "group": "Card 1"
      },
      "card1Icon": {
        "dataType": "text",
        "displayName": "Card 1 Icon",
        "defaultValue": "◎",
        "group": "Card 1"
      },
      "card2Title": {
        "dataType": "text",
        "displayName": "Card 2 Title",
        "defaultValue": "Design",
        "group": "Card 2"
      },
      "card2Description": {
        "dataType": "text",
        "displayName": "Card 2 Description",
        "defaultValue": "Beautiful, intuitive interfaces that delight users and drive engagement.",
        "group": "Card 2"
      },
      "card2Icon": {
        "dataType": "text",
        "displayName": "Card 2 Icon",
        "defaultValue": "◈",
        "group": "Card 2"
      },
      "card3Title": {
        "dataType": "text",
        "displayName": "Card 3 Title",
        "defaultValue": "Development",
        "group": "Card 3"
      },
      "card3Description": {
        "dataType": "text",
        "displayName": "Card 3 Description",
        "defaultValue": "Robust, scalable solutions built with cutting-edge technology.",
        "group": "Card 3"
      },
      "card3Icon": {
        "dataType": "text",
        "displayName": "Card 3 Icon",
        "defaultValue": "⬡",
        "group": "Card 3"
      },
      "card4Title": {
        "dataType": "text",
        "displayName": "Card 4 Title",
        "defaultValue": "Growth",
        "group": "Card 4"
      },
      "card4Description": {
        "dataType": "text",
        "displayName": "Card 4 Description",
        "defaultValue": "Continuous optimization and scaling to maximize your success.",
        "group": "Card 4"
      },
      "card4Icon": {
        "dataType": "text",
        "displayName": "Card 4 Icon",
        "defaultValue": "△",
        "group": "Card 4"
      },
      "baseElevation": {
        "dataType": "select",
        "displayName": "Base Elevation (px)",
        "defaultValue": "0",
        "options": ["0", "10", "20"],
        "group": "Layout"
      },
      "elevationStep": {
        "dataType": "select",
        "displayName": "Elevation Step (px)",
        "defaultValue": "40",
        "options": ["20", "30", "40", "50", "60"],
        "group": "Layout"
      },
      "cardWidth": {
        "dataType": "select",
        "displayName": "Card Width",
        "defaultValue": "280",
        "options": ["240", "260", "280", "300", "320"],
        "group": "Layout"
      },
      "cardGap": {
        "dataType": "select",
        "displayName": "Card Gap (px)",
        "defaultValue": "24",
        "options": ["16", "20", "24", "32"],
        "group": "Layout"
      },
      "hoverLift": {
        "dataType": "select",
        "displayName": "Hover Lift (px)",
        "defaultValue": "20",
        "options": ["10", "15", "20", "30"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#F8F9FA",
        "group": "Colors"
