      "cardBorderColor": {
        "dataType": "color",
        "displayName": "Card Border Color",
        "defaultValue": "#E9ECEF",
        "group": "Colors"
      },
      "titleColor": {
        "dataType": "color",
        "displayName": "Title Color",
        "defaultValue": "#212529",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "subtitleColor": {
        "dataType": "color",
        "displayName": "Subtitle Color",
        "defaultValue": "#6C757D",
        "group": "Colors"
      },
      "iconColor": {
        "dataType": "color",
        "displayName": "Icon Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#212529",
        "group": "Colors"
      },
      "shadowColor": {
        "dataType": "color",
        "displayName": "Shadow Color",
        "defaultValue": "#000000",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const [hoveredIndex, setHoveredIndex] = React.useState(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const sectionTitle = config?.sectionTitle || 'Our Services';
  const sectionSubtitle = config?.sectionSubtitle || 'Comprehensive solutions tailored to your needs';

  const cards = [
    {
      title: config?.card1Title || 'Strategy',
      description: config?.card1Description || 'Data-driven strategies that align with your business goals.',
      icon: config?.card1Icon || '◎'
    },
    {
      title: config?.card2Title || 'Design',
      description: config?.card2Description || 'Beautiful, intuitive interfaces that delight users.',
      icon: config?.card2Icon || '◈'
    },
    {
      title: config?.card3Title || 'Development',
      description: config?.card3Description || 'Robust, scalable solutions built with cutting-edge technology.',
      icon: config?.card3Icon || '⬡'
    },
    {
      title: config?.card4Title || 'Growth',
      description: config?.card4Description || 'Continuous optimization and scaling to maximize success.',
      icon: config?.card4Icon || '△'
    }
  ];

  const baseElevation = parseInt(config?.baseElevation || '0');
  const elevationStep = parseInt(config?.elevationStep || '40');
  const cardWidth = parseInt(config?.cardWidth || '280');
  const cardGap = parseInt(config?.cardGap || '24');
  const hoverLift = parseInt(config?.hoverLift || '20');

  const backgroundColor = config?.backgroundColor || '#F8F9FA';
  const cardBackgroundColor = config?.cardBackgroundColor || '#FFFFFF';
  const cardBorderColor = config?.cardBorderColor || '#E9ECEF';
  const titleColor = config?.titleColor || '#212529';
  const textColor = config?.textColor || '#495057';
  const subtitleColor = config?.subtitleColor || '#6C757D';
  const iconColor = config?.iconColor || '#495057';
  const accentColor = config?.accentColor || '#212529';
  const shadowColor = config?.shadowColor || '#000000';

  const getCardStyle = (index) => {
    const isHovered = hoveredIndex === index;
    const elevation = baseElevation + (index * elevationStep);
    const translateY = isHovered ? -hoverLift : 0;
    const shadowBlur = 20 + (index * 8);
    const shadowOpacity = isHovered ? 0.15 : 0.08 + (index * 0.02);

    return {
      position: 'relative',
      width: cardWidth + 'px',
      padding: '32px 28px',
      backgroundColor: cardBackgroundColor,
      border: `1px solid ${cardBorderColor}`,
      borderRadius: '12px',
      marginTop: -elevation + 'px',
      transform: `translateY(${translateY}px)`,
      boxShadow: `0 ${10 + index * 5}px ${shadowBlur}px ${shadowColor}${Math.round(shadowOpacity * 255).toString(16).padStart(2, '0')}`,
      transition: prefersReducedMotion ? 'none' : 'transform 400ms cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 400ms ease-out',
      cursor: 'pointer',
      zIndex: isHovered ? 10 : index
    };
  };

  return (
    <div
      className="staggered-elevation-cards"
      style={{
        backgroundColor,
        padding: '80px 40px 120px',
        minHeight: '600px'
      }}
    >
      {/* Section Header */}
      <div
        style={{
          textAlign: 'center',
          marginBottom: '60px',
          maxWidth: '600px',
          marginLeft: 'auto',
          marginRight: 'auto'
        }}
      >
        <h2
          style={{
            fontSize: '36px',
            fontWeight: '500',
            color: titleColor,
            margin: '0 0 16px 0',
            letterSpacing: '-0.02em'
          }}
        >
          {sectionTitle}
        </h2>
        <p
          style={{
            fontSize: '16px',
            fontWeight: '400',
            color: subtitleColor,
            margin: 0,
            lineHeight: '1.6'
          }}
        >
          {sectionSubtitle}
        </p>
      </div>

      {/* Cards Container */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'flex-end',
          gap: cardGap + 'px',
          flexWrap: 'wrap',
          paddingTop: (cards.length - 1) * elevationStep + 'px'
        }}
      >
        {cards.map((card, index) => (
          <div
            key={index}
            style={getCardStyle(index)}
            onMouseEnter={() => setHoveredIndex(index)}
            onMouseLeave={() => setHoveredIndex(null)}
            role="article"
            tabIndex={0}
          >
            {/* Step Number */}
            <div
              style={{
                position: 'absolute',
                top: '-12px',
                left: '24px',
                width: '24px',
                height: '24px',
                borderRadius: '50%',
                backgroundColor: accentColor,
                color: cardBackgroundColor,
                fontSize: '12px',
                fontWeight: '500',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}
            >
              {index + 1}
            </div>

            {/* Icon */}
            <div
              style={{
                fontSize: '32px',
                color: iconColor,
                marginBottom: '20px',
                opacity: hoveredIndex === index ? 1 : 0.7,
                transition: prefersReducedMotion ? 'none' : 'opacity 300ms ease-out'
              }}
            >
              {card.icon}
            </div>

            {/* Title */}
            <h3
              style={{
                fontSize: '20px',
                fontWeight: '500',
                color: titleColor,
                margin: '0 0 12px 0',
                letterSpacing: '-0.01em'
              }}
            >
              {card.title}
            </h3>

            {/* Description */}
            <p
              style={{
                fontSize: '14px',
                fontWeight: '400',
                color: textColor,
                margin: 0,
                lineHeight: '1.6'
              }}
            >
              {card.description}
            </p>

            {/* Bottom Accent Line */}
            <div
              style={{
                position: 'absolute',
                bottom: 0,
                left: '24px',
                right: '24px',
                height: '2px',
                backgroundColor: accentColor,
                transform: `scaleX(${hoveredIndex === index ? 1 : 0})`,
                transformOrigin: 'left',
                transition: prefersReducedMotion ? 'none' : 'transform 300ms ease-out',
                borderRadius: '1px'
              }}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

