};

function Component({ config = {} }) {
  const [hoveredIndex, setHoveredIndex] = React.useState(null);
  const [centerHovered, setCenterHovered] = React.useState(false);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const sectionTitle = config?.sectionTitle || 'Our Core Values';

  const centerCard = {
    title: config?.centerTitle || 'Excellence',
    description: config?.centerDescription || 'The foundation of everything we do',
    icon: config?.centerIcon || '★'
  };

  const orbitalValues = [
    { title: config?.value1Title || 'Innovation', icon: config?.value1Icon || '◇' },
    { title: config?.value2Title || 'Integrity', icon: config?.value2Icon || '◈' },
    { title: config?.value3Title || 'Collaboration', icon: config?.value3Icon || '◎' },
    { title: config?.value4Title || 'Impact', icon: config?.value4Icon || '△' },
    { title: config?.value5Title || 'Growth', icon: config?.value5Icon || '⬡' }
  ];

  const orbitRadius = parseInt(config?.orbitRadius || '200');
  const centerCardSize = parseInt(config?.centerCardSize || '180');
  const orbitalCardSize = parseInt(config?.orbitalCardSize || '100');
  const showConnectors = config?.showConnectors !== false;

  const backgroundColor = config?.backgroundColor || '#0F172A';
  const centerCardBg = config?.centerCardBg || '#1E293B';
  const orbitalCardBg = config?.orbitalCardBg || '#1E293B';
  const titleColor = config?.titleColor || '#F8FAFC';
  const textColor = config?.textColor || '#94A3B8';
  const accentColor = config?.accentColor || '#3B82F6';
  const connectorColor = config?.connectorColor || '#334155';

  const uniqueId = React.useMemo(() => {
    return typeof React.useId === 'function'
      ? React.useId().replace(/:/g, '')
      : `id-${Math.random().toString(36).substr(2, 9)}`;
  }, []);

  const getOrbitalPosition = (index, total) => {
    const angle = (index / total) * Math.PI * 2 - Math.PI / 2;
    return {
      x: Math.cos(angle) * orbitRadius,
      y: Math.sin(angle) * orbitRadius
    };
  };

  const getOrbitalCardStyle = (index) => {
    const pos = getOrbitalPosition(index, orbitalValues.length);
    const isHovered = hoveredIndex === index;
    const scale = isHovered ? 1.15 : 1;

    return {
      position: 'absolute',
      width: orbitalCardSize + 'px',
      height: orbitalCardSize + 'px',
      left: '50%',
      top: '50%',
      transform: `translate(-50%, -50%) translate(${pos.x}px, ${pos.y}px) scale(${scale})`,
      backgroundColor: orbitalCardBg,
      borderRadius: '16px',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      cursor: 'pointer',
      border: `1px solid ${isHovered ? accentColor : connectorColor}`,
      boxShadow: isHovered 
        ? `0 0 30px ${accentColor}40` 
        : '0 4px 20px rgba(0,0,0,0.3)',
      transition: prefersReducedMotion ? 'none' : 'all 300ms cubic-bezier(0.34, 1.56, 0.64, 1)',
      zIndex: isHovered ? 10 : 1
    };
  };

  const containerSize = orbitRadius * 2 + orbitalCardSize + 100;

  return (
    <div
      className="orbital-value-cards"
      style={{
        backgroundColor,
        padding: '80px 40px',
        minHeight: '700px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center'
      }}
    >
      {/* Section Title */}
      <h2
        style={{
          fontSize: '32px',
          fontWeight: '500',
          color: titleColor,
          margin: '0 0 60px 0',
          letterSpacing: '-0.02em',
          textAlign: 'center'
        }}
      >
        {sectionTitle}
      </h2>

      {/* Orbital Container */}
      <div
        style={{
          position: 'relative',
          width: containerSize + 'px',
          height: containerSize + 'px'
        }}
      >
        {/* Connector Lines */}
        {showConnectors && (
          <svg
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              pointerEvents: 'none'
            }}
            aria-hidden="true"
          >
            {/* Orbit Ring */}
            <circle
              cx="50%"
              cy="50%"
              r={orbitRadius}
              fill="none"
              stroke={connectorColor}
              strokeWidth="1"
              strokeDasharray="4 8"
              opacity="0.5"
            />

            {/* Connector Lines to Center */}
            {orbitalValues.map((_, index) => {
              const pos = getOrbitalPosition(index, orbitalValues.length);
              const isHovered = hoveredIndex === index;
              return (
                <line
                  key={`connector-${index}`}
                  x1="50%"
                  y1="50%"
                  x2={`calc(50% + ${pos.x}px)`}
                  y2={`calc(50% + ${pos.y}px)`}
                  stroke={isHovered ? accentColor : connectorColor}
                  strokeWidth={isHovered ? "2" : "1"}
                  opacity={isHovered ? "1" : "0.3"}
                  style={{
                    transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
                  }}
                />
              );
            })}
          </svg>
        )}

        {/* Center Card */}
        <div
          style={{
            position: 'absolute',
            width: centerCardSize + 'px',
            height: centerCardSize + 'px',
            left: '50%',
            top: '50%',
            transform: `translate(-50%, -50%) scale(${centerHovered ? 1.05 : 1})`,
            backgroundColor: centerCardBg,
            borderRadius: '50%',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            border: `2px solid ${centerHovered ? accentColor : connectorColor}`,
            boxShadow: centerHovered 
              ? `0 0 60px ${accentColor}50` 
              : `0 10px 40px rgba(0,0,0,0.4)`,
            transition: prefersReducedMotion ? 'none' : 'all 400ms cubic-bezier(0.34, 1.56, 0.64, 1)',
            cursor: 'pointer',
            zIndex: 5
          }}
          onMouseEnter={() => setCenterHovered(true)}
          onMouseLeave={() => setCenterHovered(false)}
          role="article"
          tabIndex={0}
        >
          <div
            style={{
              fontSize: '36px',
              color: accentColor,
              marginBottom: '8px'
            }}
          >
            {centerCard.icon}
          </div>
          <h3
            style={{
              fontSize: '16px',
              fontWeight: '500',
              color: titleColor,
              margin: '0 0 4px 0',
              textAlign: 'center'
            }}
          >
            {centerCard.title}
          </h3>
          <p
            style={{
              fontSize: '11px',
              color: textColor,
              margin: 0,
              textAlign: 'center',
              padding: '0 16px',
              lineHeight: '1.4'
            }}
          >
            {centerCard.description}
          </p>
        </div>

        {/* Orbital Cards */}
        {orbitalValues.map((value, index) => (
          <div
            key={`${uniqueId}-orbital-${index}`}
            style={getOrbitalCardStyle(index)}
            onMouseEnter={() => setHoveredIndex(index)}
            onMouseLeave={() => setHoveredIndex(null)}
            role="article"
            tabIndex={0}
          >
            <div
              style={{
                fontSize: '24px',
                color: hoveredIndex === index ? accentColor : textColor,
                marginBottom: '8px',
                transition: prefersReducedMotion ? 'none' : 'color 300ms ease-out'
              }}
            >
              {value.icon}
            </div>
            <span
              style={{
                fontSize: '12px',
                fontWeight: '500',
                color: titleColor,
                textAlign: 'center'
              }}
            >
              {value.title}
            </span>
          </div>
        ))}
      </div>

      {/* Selected Value Description */}
      <div
        style={{
          marginTop: '40px',
          height: '40px',
          display: 'flex',
