function Component({ config = {} }) {
  const [hoveredStep, setHoveredStep] = React.useState(null);
  const [expandedStep, setExpandedStep] = React.useState(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const sectionTitle = config?.sectionTitle || 'How It Works';
  const sectionSubtitle = config?.sectionSubtitle || 'A simple four-step process to success';

  const steps = [
    {
      title: config?.step1Title || 'Discovery',
      description: config?.step1Description || 'We learn about your business, goals, and challenges.'
    },
    {
      title: config?.step2Title || 'Strategy',
      description: config?.step2Description || 'Our team develops a customized roadmap.'
    },
    {
      title: config?.step3Title || 'Execution',
      description: config?.step3Description || 'We implement solutions with precision.'
    },
    {
      title: config?.step4Title || 'Growth',
      description: config?.step4Description || 'Continuous optimization for lasting success.'
    }
  ];

  const cascadeOffset = parseInt(config?.cascadeOffset || '60');
  const cardWidth = parseInt(config?.cardWidth || '300');
  const showConnectors = config?.showConnectors !== false;

  const backgroundColor = config?.backgroundColor || '#0B1120';
  const cardBackgroundColor = config?.cardBackgroundColor || '#131B2E';
  const cardBorderColor = config?.cardBorderColor || '#1E2A45';
  const titleColor = config?.titleColor || '#F8FAFC';
  const textColor = config?.textColor || '#94A3B8';
  const accentColor = config?.accentColor || '#3B82F6';
  const numberColor = config?.numberColor || '#1E3A8A';
  const connectorColor = config?.connectorColor || '#1E3A8A';

  const uniqueId = React.useMemo(() => {
    return typeof React.useId === 'function'
      ? React.useId().replace(/:/g, '')
      : `id-${Math.random().toString(36).substr(2, 9)}`;
  }, []);

  const getCardStyle = (index) => {
    const isHovered = hoveredStep === index;
    const isExpanded = expandedStep === index;
    const offsetX = index * cascadeOffset;
    const offsetY = index * cascadeOffset;

    return {
      position: 'relative',
      width: cardWidth + 'px',
      marginLeft: offsetX + 'px',
      marginTop: index === 0 ? 0 : -20 + 'px',
      padding: '28px',
      backgroundColor: cardBackgroundColor,
      border: `1px solid ${isHovered ? accentColor : cardBorderColor}`,
      borderRadius: '16px',
      cursor: 'pointer',
      transform: `translateY(${isHovered ? -8 : 0}px)`,
      boxShadow: isHovered 
        ? `0 20px 40px rgba(0,0,0,0.3), 0 0 0 1px ${accentColor}40`
        : '0 4px 20px rgba(0,0,0,0.2)',
      transition: prefersReducedMotion ? 'none' : 'all 400ms cubic-bezier(0.34, 1.56, 0.64, 1)',
      zIndex: isHovered ? 10 : steps.length - index
    };
  };

  return (
    <div
      className="cascading-timeline-cards"
      style={{
        backgroundColor,
        padding: '80px 40px',
        minHeight: '800px',
        overflow: 'hidden'
      }}
    >
      {/* Section Header */}
      <div
        style={{
          maxWidth: '600px',
          marginBottom: '60px'
        }}
      >
        <p
          style={{
            fontSize: '13px',
            fontWeight: '500',
            color: accentColor,
            margin: '0 0 12px 0',
            letterSpacing: '0.1em',
            textTransform: 'uppercase'
          }}
        >
          Process
        </p>
        <h2
          style={{
            fontSize: '40px',
            fontWeight: '500',
            color: titleColor,
            margin: '0 0 16px 0',
            letterSpacing: '-0.02em',
            lineHeight: '1.2'
          }}
        >
          {sectionTitle}
        </h2>
        <p
          style={{
            fontSize: '16px',
            color: textColor,
            margin: 0,
            lineHeight: '1.6'
          }}
        >
          {sectionSubtitle}
        </p>
      </div>

      {/* Cascading Cards Container */}
      <div
        style={{
          position: 'relative',
          maxWidth: '900px',
          margin: '0 auto'
        }}
      >
        {/* Connector Line */}
        {showConnectors && (
          <svg
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              pointerEvents: 'none',
              zIndex: 0
            }}
            aria-hidden="true"
          >
            <defs>
              <linearGradient id={`${uniqueId}-line-gradient`} x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor={accentColor} stopOpacity="0.8" />
                <stop offset="100%" stopColor={connectorColor} stopOpacity="0.3" />
              </linearGradient>
            </defs>
            <line
              x1="60"
              y1="60"
              x2={60 + (steps.length - 1) * cascadeOffset + cardWidth - 60}
              y2={60 + (steps.length - 1) * cascadeOffset + 100}
              stroke={`url(#${uniqueId}-line-gradient)`}
              strokeWidth="2"
              strokeDasharray="8 8"
            />
          </svg>
        )}

        {/* Cards */}
        {steps.map((step, index) => (
          <div
            key={`${uniqueId}-step-${index}`}
            style={getCardStyle(index)}
            onMouseEnter={() => setHoveredStep(index)}
            onMouseLeave={() => setHoveredStep(null)}
            onClick={() => setExpandedStep(expandedStep === index ? null : index)}
            role="article"
            tabIndex={0}
          >
            {/* Step Number */}
            <div
              style={{
                position: 'absolute',
                top: '-16px',
                left: '24px',
                width: '32px',
                height: '32px',
                borderRadius: '50%',
                backgroundColor: hoveredStep === index ? accentColor : numberColor,
                color: titleColor,
                fontSize: '14px',
                fontWeight: '600',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                transition: prefersReducedMotion ? 'none' : 'background-color 300ms ease-out',
                boxShadow: '0 4px 12px rgba(0,0,0,0.3)'
              }}
            >
              {String(index + 1).padStart(2, '0')}
            </div>

            {/* Content */}
            <div style={{ marginTop: '8px' }}>
              <h3
                style={{
                  fontSize: '20px',
                  fontWeight: '500',
                  color: titleColor,
                  margin: '0 0 12px 0',
                  letterSpacing: '-0.01em'
                }}
              >
                {step.title}
              </h3>
              <p
                style={{
                  fontSize: '14px',
                  color: textColor,
                  margin: 0,
                  lineHeight: '1.6',
                  maxHeight: expandedStep === index ? '200px' : '60px',
                  overflow: 'hidden',
                  transition: prefersReducedMotion ? 'none' : 'max-height 300ms ease-out'
                }}
              >
                {step.description}
              </p>
            </div>

            {/* Expand Indicator */}
            <div
              style={{
                marginTop: '16px',
                display: 'flex',
                alignItems: 'center',
                gap: '6px',
                color: accentColor,
                fontSize: '13px',
                fontWeight: '500',
                opacity: hoveredStep === index ? 1 : 0,
                transform: `translateY(${hoveredStep === index ? 0 : 8}px)`,
                transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
              }}
            >
              {expandedStep === index ? 'Show less' : 'Learn more'}
              <span style={{
                transform: `rotate(${expandedStep === index ? 180 : 0}deg)`,
                transition: prefersReducedMotion ? 'none' : 'transform 300ms ease-out'
              }}>↓</span>
            </div>

            {/* Progress Bar */}
            <div
              style={{
                position: 'absolute',
                bottom: 0,
                left: 0,
                right: 0,
                height: '3px',
                backgroundColor: cardBorderColor,
                borderRadius: '0 0 16px 16px',
                overflow: 'hidden'
              }}
            >
              <div
                style={{
                  width: `${(index + 1) / steps.length * 100}%`,
                  height: '100%',
                  backgroundColor: accentColor,
                  transition: prefersReducedMotion ? 'none' : 'width 500ms ease-out'
                }}
              />
            </div>
          </div>
        ))}
      </div>

      {/* Progress Indicator */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          gap: '12px',
          marginTop: '60px'
        }}
      >
        {steps.map((_, index) => (
          <button
            key={`${uniqueId}-indicator-${index}`}
            onClick={() => setHoveredStep(index)}
            style={{
              width: hoveredStep === index ? '32px' : '8px',
              height: '8px',
              borderRadius: '4px',
              backgroundColor: hoveredStep === index ? accentColor : cardBorderColor,
              border: 'none',
              padding: 0,
              cursor: 'pointer',
              transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
            }}
            aria-label={`Step ${index + 1}`}
          />
        ))}
      </div>
    </div>
  );
}

