                    transform: `translateX(${isHovered ? 0 : -10}px)`,
                    transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
                  }}
                >
                  Learn more
                  <span>→</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Bottom CTA */}
      <div
        style={{
          maxWidth: '1200px',
          margin: '60px auto 0',
          textAlign: 'center'
        }}
      >
        <button
          style={{
            padding: '16px 32px',
            backgroundColor: titleColor,
            color: backgroundColor,
            border: 'none',
            borderRadius: '8px',
            fontSize: '14px',
            fontWeight: '500',
            cursor: 'pointer',
            transition: prefersReducedMotion ? 'none' : 'all 200ms ease-out'
          }}
          onMouseEnter={(e) => {
            e.target.style.transform = 'translateY(-2px)';
            e.target.style.boxShadow = '0 10px 20px rgba(0,0,0,0.15)';
          }}
          onMouseLeave={(e) => {
            e.target.style.transform = 'translateY(0)';
            e.target.style.boxShadow = 'none';
          }}
        >
          View All Services
        </button>
      </div>
    </div>
  );
}

