function Component({ config = {} }) {
  const cardsString = config?.cards || 'Innovation,Design,Strategy,Technology,Excellence';
  const descriptionsString = config?.cardDescriptions || 'Pushing boundaries of possibility,Crafting elegant solutions,Building for the future,Enabling transformation,Pursuing perfection';
  const springStiffness = parseInt(config?.springStiffness || '300');
  const springDamping = parseInt(config?.springDamping || '25');
  const dragElasticity = parseFloat(config?.dragElasticity || '0.2');
  const throwVelocity = parseInt(config?.throwVelocity || '500');
  const stackSpread = parseInt(config?.stackSpread || '8');
  const cardWidth = parseInt(config?.cardWidth || '320');
  const cardHeight = parseInt(config?.cardHeight || '400');
  const borderRadius = parseInt(config?.borderRadius || '12');
  const backgroundColor = config?.backgroundColor || '#F4F4F5';
  const cardBackground = config?.cardBackground || '#FFFFFF';
  const cardBorder = config?.cardBorder || '#E4E4E7';
  const textColor = config?.textColor || '#18181B';
  const subtextColor = config?.subtextColor || '#71717A';
  const accentColor = config?.accentColor || '#3F3F46';
  const shadowColor = config?.shadowColor || '#18181B';
  const titleFontSize = parseInt(config?.titleFontSize || '28');
  const fontWeight = config?.fontWeight || '500';
  const letterSpacing = config?.letterSpacing || '0.025em';

  const cardData = React.useMemo(() => {
    const titles = cardsString.split(',').map(t => t.trim()).filter(Boolean);
    const descriptions = descriptionsString.split(',').map(d => d.trim());
    return titles.map((title, i) => ({
      id: i,
      title,
      description: descriptions[i] || ''
    }));
  }, [cardsString, descriptionsString]);

  const [cards, setCards] = React.useState(cardData);
  const [draggedCard, setDraggedCard] = React.useState(null);
  const [isDragging, setIsDragging] = React.useState(false);
  const cardRefs = React.useRef([]);
  const dragStartRef = React.useRef({ x: 0, y: 0 });
  const currentPosRef = React.useRef({ x: 0, y: 0 });
  const velocityRef = React.useRef({ x: 0, y: 0 });
  const lastPosRef = React.useRef({ x: 0, y: 0 });
  const lastTimeRef = React.useRef(0);
  const animationRef = React.useRef(null);
  const springRef = React.useRef({ x: 0, y: 0, vx: 0, vy: 0 });

  const prefersReducedMotion = React.useMemo(() => {
    return typeof window !== 'undefined'
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
      : false;
  }, []);

  React.useEffect(() => {
    setCards(cardData);
  }, [cardData]);

  const handleDragStart = (e, cardIndex) => {
    if (cardIndex !== 0) return;

    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;

    dragStartRef.current = { x: clientX, y: clientY };
    currentPosRef.current = { x: 0, y: 0 };
    lastPosRef.current = { x: clientX, y: clientY };
    lastTimeRef.current = Date.now();
    velocityRef.current = { x: 0, y: 0 };

    setDraggedCard(cardIndex);
    setIsDragging(true);
  };

  const handleDrag = React.useCallback((e) => {
    if (!isDragging || draggedCard === null) return;

    e.preventDefault();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;

    const now = Date.now();
    const dt = Math.max(1, now - lastTimeRef.current);

    velocityRef.current = {
      x: (clientX - lastPosRef.current.x) / dt * 1000,
      y: (clientY - lastPosRef.current.y) / dt * 1000
    };

    lastPosRef.current = { x: clientX, y: clientY };
    lastTimeRef.current = now;

    currentPosRef.current = {
      x: (clientX - dragStartRef.current.x) * (1 + dragElasticity),
      y: (clientY - dragStartRef.current.y) * (1 + dragElasticity)
    };

    if (cardRefs.current[draggedCard]) {
      const rotation = currentPosRef.current.x * 0.05;
      cardRefs.current[draggedCard].style.transform = 
        `translate(${currentPosRef.current.x}px, ${currentPosRef.current.y}px) rotate(${rotation}deg) scale(1.02)`;
    }
  }, [isDragging, draggedCard, dragElasticity]);

  const handleDragEnd = React.useCallback(() => {
    if (!isDragging || draggedCard === null) return;

    const velocity = velocityRef.current;
    const position = currentPosRef.current;
    const throwThreshold = throwVelocity;

    const shouldThrow = Math.abs(velocity.x) > throwThreshold || Math.abs(position.x) > cardWidth * 0.5;

    if (shouldThrow && !prefersReducedMotion) {
      const direction = velocity.x > 0 ? 1 : (position.x > 0 ? 1 : -1);

      springRef.current = {
        x: position.x,
        y: position.y,
        vx: velocity.x,
        vy: velocity.y
      };

      const animateThrow = () => {
        const spring = springRef.current;
        const targetX = direction * (window.innerWidth + cardWidth);
        const targetY = position.y + velocity.y * 0.5;

        const dx = targetX - spring.x;
        const dy = targetY - spring.y;

        const ax = dx * (springStiffness / 1000) - spring.vx * (springDamping / 100);
        const ay = dy * (springStiffness / 1000) - spring.vy * (springDamping / 100);

        spring.vx += ax;
        spring.vy += ay;
        spring.x += spring.vx * 0.016;
        spring.y += spring.vy * 0.016;

        if (cardRefs.current[draggedCard]) {
          const rotation = spring.x * 0.03;
          cardRefs.current[draggedCard].style.transform = 
            `translate(${spring.x}px, ${spring.y}px) rotate(${rotation}deg)`;
        }

        if (Math.abs(spring.x) < Math.abs(targetX) * 0.9) {
          animationRef.current = requestAnimationFrame(animateThrow);
        } else {
          setCards(prev => {
            const newCards = [...prev];
            const [removed] = newCards.splice(0, 1);
            newCards.push(removed);
            return newCards;
          });

          if (cardRefs.current[draggedCard]) {
            cardRefs.current[draggedCard].style.transform = '';
          }
        }
      };

      animationRef.current = requestAnimationFrame(animateThrow);
    } else {
      springRef.current = {
        x: position.x,
        y: position.y,
        vx: 0,
        vy: 0
      };

      const animateReturn = () => {
        const spring = springRef.current;

        const ax = -spring.x * (springStiffness / 1000) - spring.vx * (springDamping / 100);
        const ay = -spring.y * (springStiffness / 1000) - spring.vy * (springDamping / 100);

        spring.vx += ax;
        spring.vy += ay;
        spring.x += spring.vx * 0.016;
        spring.y += spring.vy * 0.016;

        if (cardRefs.current[draggedCard]) {
          const rotation = spring.x * 0.05;
          cardRefs.current[draggedCard].style.transform = 
            `translate(${spring.x}px, ${spring.y}px) rotate(${rotation}deg)`;
        }

        if (Math.abs(spring.x) > 0.5 || Math.abs(spring.y) > 0.5 || Math.abs(spring.vx) > 0.5 || Math.abs(spring.vy) > 0.5) {
          animationRef.current = requestAnimationFrame(animateReturn);
        } else {
          if (cardRefs.current[draggedCard]) {
            cardRefs.current[draggedCard].style.transform = '';
          }
        }
      };

      if (!prefersReducedMotion) {
        animationRef.current = requestAnimationFrame(animateReturn);
      } else {
        if (cardRefs.current[draggedCard]) {
          cardRefs.current[draggedCard].style.transform = '';
        }
      }
    }

    setIsDragging(false);
    setDraggedCard(null);
  }, [isDragging, draggedCard, cardWidth, throwVelocity, springStiffness, springDamping, prefersReducedMotion]);

  React.useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleDrag);
      window.addEventListener('mouseup', handleDragEnd);
      window.addEventListener('touchmove', handleDrag, { passive: false });
      window.addEventListener('touchend', handleDragEnd);
    }

    return () => {
      window.removeEventListener('mousemove', handleDrag);
      window.removeEventListener('mouseup', handleDragEnd);
      window.removeEventListener('touchmove', handleDrag);
      window.removeEventListener('touchend', handleDragEnd);
    };
  }, [isDragging, handleDrag, handleDragEnd]);

  React.useEffect(() => {
    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, []);

  const getCardStyle = (index) => {
    const isTop = index === 0;
    const stackOffset = index * stackSpread;
    const scaleReduction = index * 0.02;
    const opacityReduction = index * 0.15;

    return {
      position: 'absolute',
      width: cardWidth,
      height: cardHeight,
      backgroundColor: cardBackground,
      border: `1px solid ${cardBorder}`,
      borderRadius: borderRadius,
      padding: '32px',
      boxSizing: 'border-box',
      cursor: isTop ? 'grab' : 'default',
      transform: `translateY(${stackOffset}px) scale(${1 - scaleReduction})`,
      opacity: 1 - opacityReduction,
      boxShadow: isTop 
        ? `0 20px 40px ${shadowColor}15, 0 8px 16px ${shadowColor}10`
        : `0 4px 12px ${shadowColor}08`,
      zIndex: cards.length - index,
      transition: prefersReducedMotion ? 'none' : (isDragging && index === 0 ? 'none' : 'all 400ms cubic-bezier(0.34, 1.56, 0.64, 1)'),
      userSelect: 'none',
      touchAction: 'none',
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'space-between'
    };
  };

  return (
    <div
      className="spring-cards"
      style={{
        position: 'relative',
        width: '100%',
        minHeight: '600px',
        backgroundColor: backgroundColor,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '60px 40px',
        boxSizing: 'border-box',
        overflow: 'hidden'
      }}
    >
      <div
        style={{
          position: 'relative',
          width: cardWidth,
          height: cardHeight + (cards.length - 1) * stackSpread
        }}
      >
        {cards.map((card, index) => (
          <div
            key={card.id}
            ref={el => cardRefs.current[index] = el}
            onMouseDown={(e) => handleDragStart(e, index)}
            onTouchStart={(e) => handleDragStart(e, index)}
            style={getCardStyle(index)}
          >
            <div>
              <div
                style={{
                  width: '48px',
                  height: '48px',
                  borderRadius: '50%',
                  backgroundColor: `${accentColor}10`,
                  border: `1px solid ${cardBorder}`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  marginBottom: '24px',
                  fontSize: '20px',
                  color: accentColor
                }}
              >
                {index + 1}
              </div>
              <h3
                style={{
                  fontSize: titleFontSize,
                  fontWeight: fontWeight,
                  letterSpacing: letterSpacing,
                  color: textColor,
                  margin: '0 0 12px 0',
                  fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
                }}
              >
                {card.title}
              </h3>
              <p
                style={{
                  fontSize: '15px',
                  lineHeight: 1.6,
                  color: subtextColor,
                  margin: 0,
                  fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
                }}
              >
                {card.description}
              </p>
            </div>

            {index === 0 && (
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                  color: subtextColor,
                  fontSize: '12px',
                  letterSpacing: '0.1em',
                  textTransform: 'uppercase',
                  fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
                }}
              >
                <span>Drag to dismiss</span>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                  <path d="M5 12h14M12 5l7 7-7 7" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
              </div>
            )}
          </div>
        ))}
      </div>

      <div
        style={{
          marginTop: '48px',
          display: 'flex',
          gap: '8px'
        }}
      >
        {cards.map((card, index) => (
          <div
            key={card.id}
            style={{
              width: '8px',
              height: '8px',
              borderRadius: '50%',
              backgroundColor: index === 0 ? accentColor : cardBorder,
              transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
            }}
          />
        ))}
      </div>
    </div>
  );
}

