    }
  ];

  const baseTiltDeg = parseInt(config?.baseTiltDeg || '8');
  const mouseTiltIntensity = config?.mouseTiltIntensity || 'medium';
  const cardWidth = parseInt(config?.cardWidth || '320');
  const cardGap = parseInt(config?.cardGap || '32');
  const perspective = parseInt(config?.perspective || '1000');

  const backgroundColor = config?.backgroundColor || '#F4F4F5';
  const cardBackgroundColor = config?.cardBackgroundColor || '#FFFFFF';
  const titleColor = config?.titleColor || '#18181B';
  const textColor = config?.textColor || '#52525B';
  const iconColor = config?.iconColor || '#3F3F46';
  const accentColor = config?.accentColor || '#18181B';
  const shadowColor = config?.shadowColor || '#000000';

  const tiltMultiplier = {
    subtle: 0.5,
    medium: 1,
    dramatic: 1.5
  }[mouseTiltIntensity] || 1;

  const handleMouseMove = (e, cardIndex) => {
    if (prefersReducedMotion) return;

    const card = cardRefs.current[cardIndex];
    if (!card) return;

    const rect = card.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;

    setMousePosition({ x, y });
  };

  const handleMouseLeave = () => {
    setMousePosition({ x: 0.5, y: 0.5 });
    setHoveredCard(null);
  };

  const getCardStyle = (index) => {
    const isHovered = hoveredCard === index;

    // Base tilt based on position (left card tilts right, right card tilts left)
    let baseTiltY = 0;
    if (index === 0) baseTiltY = baseTiltDeg;
    if (index === 2) baseTiltY = -baseTiltDeg;

    // Mouse-driven tilt when hovered
    let rotateX = 0;
    let rotateY = baseTiltY;

    if (isHovered && !prefersReducedMotion) {
      const maxTilt = 15 * tiltMultiplier;
      rotateX = (mousePosition.y - 0.5) * -maxTilt;
      rotateY = (mousePosition.x - 0.5) * maxTilt;
    }

    return {
      width: cardWidth + 'px',
      padding: '36px 28px',
      backgroundColor: cardBackgroundColor,
      borderRadius: '16px',
      transform: `perspective(${perspective}px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) ${isHovered ? 'translateY(-8px) scale(1.02)' : ''}`,
      boxShadow: isHovered
        ? `0 30px 60px ${shadowColor}20, 0 0 0 1px ${accentColor}10`
        : `0 10px 30px ${shadowColor}08`,
      transition: prefersReducedMotion ? 'none' : 'transform 200ms ease-out, box-shadow 300ms ease-out',
      cursor: 'pointer',
      transformStyle: 'preserve-3d',
      position: 'relative'
    };
  };

  const uniqueId = React.useMemo(() => {
    return typeof React.useId === 'function'
      ? React.useId().replace(/:/g, '')
      : `id-${Math.random().toString(36).substr(2, 9)}`;
  }, []);

  return (
    <div
      className="perspective-tilt-cards"
      ref={containerRef}
      style={{
        backgroundColor,
        padding: '80px 40px',
        minHeight: '700px'
      }}
    >
      {/* Section Header */}
      <div
        style={{
          textAlign: 'center',
          maxWidth: '600px',
          margin: '0 auto 60px'
        }}
      >
        <h2
          style={{
            fontSize: '40px',
            fontWeight: '500',
            color: titleColor,
            margin: '0 0 16px 0',
            letterSpacing: '-0.02em'
          }}
        >
          {sectionTitle}
        </h2>
        <p
          style={{
            fontSize: '16px',
            color: textColor,
            margin: 0,
            lineHeight: '1.6'
          }}
        >
          {sectionSubtitle}
        </p>
      </div>

      {/* Cards Container */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          gap: cardGap + 'px',
          flexWrap: 'wrap',
          perspective: perspective + 'px'
        }}
      >
        {cards.map((card, index) => (
          <div
            key={`${uniqueId}-card-${index}`}
            ref={el => cardRefs.current[index] = el}
            style={getCardStyle(index)}
            onMouseMove={(e) => {
              setHoveredCard(index);
              handleMouseMove(e, index);
            }}
            onMouseLeave={handleMouseLeave}
            role="article"
            tabIndex={0}
          >
            {/* Shine Effect */}
            {hoveredCard === index && !prefersReducedMotion && (
              <div
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  background: `radial-gradient(circle at ${mousePosition.x * 100}% ${mousePosition.y * 100}%, rgba(255,255,255,0.3) 0%, transparent 50%)`,
                  borderRadius: '16px',
                  pointerEvents: 'none',
                  zIndex: 1
                }}
              />
            )}

            {/* Icon */}
            <div
              style={{
                width: '56px',
                height: '56px',
                borderRadius: '12px',
                backgroundColor: `${iconColor}08`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                marginBottom: '24px',
                fontSize: '24px',
                color: hoveredCard === index ? accentColor : iconColor,
                transition: prefersReducedMotion ? 'none' : 'color 300ms ease-out',
                transform: 'translateZ(20px)',
                position: 'relative',
                zIndex: 2
              }}
            >
              {card.icon}
            </div>

            {/* Title */}
            <h3
              style={{
                fontSize: '22px',
                fontWeight: '500',
                color: titleColor,
                margin: '0 0 12px 0',
                letterSpacing: '-0.01em',
                transform: 'translateZ(30px)',
                position: 'relative',
                zIndex: 2
              }}
            >
              {card.title}
            </h3>

            {/* Description */}
            <p
              style={{
                fontSize: '15px',
                color: textColor,
                margin: '0 0 24px 0',
                lineHeight: '1.6',
                transform: 'translateZ(15px)',
                position: 'relative',
                zIndex: 2
              }}
            >
              {card.description}
            </p>

            {/* CTA Link */}
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                color: accentColor,
                fontSize: '14px',
                fontWeight: '500',
                transform: 'translateZ(25px)',
                position: 'relative',
                zIndex: 2
              }}
            >
              Learn more
              <span
                style={{
                  transform: `translateX(${hoveredCard === index ? 4 : 0}px)`,
                  transition: prefersReducedMotion ? 'none' : 'transform 300ms ease-out'
                }}
              >
                →
              </span>
            </div>

            {/* Bottom Border Accent */}
            <div
              style={{
                position: 'absolute',
                bottom: 0,
                left: '28px',
                right: '28px',
                height: '3px',
                backgroundColor: accentColor,
                borderRadius: '2px',
                transform: `scaleX(${hoveredCard === index ? 1 : 0})`,
                transformOrigin: 'center',
                transition: prefersReducedMotion ? 'none' : 'transform 300ms ease-out'
              }}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

