function Component({ config = {} }) {
  const [hoveredIndex, setHoveredIndex] = React.useState(null);

  const prefersReducedMotion = typeof window !== 'undefined'
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
    : false;

  const sectionTitle = config?.sectionTitle || 'Our Values';
  const sectionSubtitle = config?.sectionSubtitle || 'The principles that guide everything we do';

  const values = [
    {
      title: config?.value1Title || 'Transparency',
      description: config?.value1Description || 'Open communication builds trust.',
      icon: config?.value1Icon || '◎'
    },
    {
      title: config?.value2Title || 'Excellence',
      description: config?.value2Description || 'We pursue the highest standards.',
      icon: config?.value2Icon || '◈'
    },
    {
      title: config?.value3Title || 'Innovation',
      description: config?.value3Description || 'Creative solutions that push boundaries.',
      icon: config?.value3Icon || '◇'
    },
    {
      title: config?.value4Title || 'Collaboration',
      description: config?.value4Description || 'Working together for greater results.',
      icon: config?.value4Icon || '△'
    }
  ];

  const cardWidth = parseInt(config?.cardWidth || '260');
  const floatAmplitude = parseInt(config?.floatAmplitude || '10');
  const floatSpeed = parseInt(config?.floatSpeed || '4');
  const enableFloat = config?.enableFloat !== false;
  const hoverLift = parseInt(config?.hoverLift || '20');

  const backgroundColor = config?.backgroundColor || '#E8E4E0';
  const cardBackgroundColor = config?.cardBackgroundColor || '#FFFFFF';
  const titleColor = config?.titleColor || '#1C1917';
  const textColor = config?.textColor || '#57534E';
  const iconColor = config?.iconColor || '#44403C';
  const shadowColor = config?.shadowColor || '#44403C';
  const accentColor = config?.accentColor || '#1C1917';

  const uniqueId = React.useMemo(() => {
    return typeof React.useId === 'function'
      ? React.useId().replace(/:/g, '')
      : `id-${Math.random().toString(36).substr(2, 9)}`;
  }, []);

  // Different base heights for each card
  const baseHeights = [0, -30, -15, -45];
  const floatOffsets = [0, 0.5, 1, 1.5]; // Stagger float animation

  const getCardStyle = (index) => {
    const isHovered = hoveredIndex === index;
    const baseHeight = baseHeights[index];
    const floatOffset = floatOffsets[index];

    const animationName = `float-${uniqueId}-${index}`;

    return {
      width: cardWidth + 'px',
      padding: '32px 28px',
      backgroundColor: cardBackgroundColor,
      borderRadius: '20px',
      cursor: 'pointer',
      transform: `translateY(${isHovered ? baseHeight - hoverLift : baseHeight}px)`,
      boxShadow: isHovered
        ? `0 ${40 + Math.abs(baseHeight)}px ${60 + Math.abs(baseHeight)}px ${shadowColor}25`
        : `0 ${20 + Math.abs(baseHeight)}px ${40 + Math.abs(baseHeight)}px ${shadowColor}15`,
      transition: prefersReducedMotion ? 'none' : 'transform 400ms cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 400ms ease-out',
      animation: enableFloat && !prefersReducedMotion && !isHovered
        ? `${animationName} ${floatSpeed}s ease-in-out infinite ${floatOffset}s`
        : 'none',
      position: 'relative',
      zIndex: isHovered ? 10 : 1
    };
  };

  // Generate keyframes for floating animation
  const floatKeyframes = values.map((_, index) => {
    const baseHeight = baseHeights[index];
    const animationName = `float-${uniqueId}-${index}`;
    return `
      @keyframes ${animationName} {
        0%, 100% { transform: translateY(${baseHeight}px); }
        50% { transform: translateY(${baseHeight - floatAmplitude}px); }
      }
    `;
  }).join('\n');

  return (
    <div
      className="floating-island-cards"
      style={{
        backgroundColor,
        padding: '100px 40px 120px',
        minHeight: '700px'
      }}
    >
      <style dangerouslySetInnerHTML={{ __html: floatKeyframes }} />

      {/* Section Header */}
      <div
        style={{
          textAlign: 'center',
          maxWidth: '600px',
          margin: '0 auto 80px'
        }}
      >
        <h2
          style={{
            fontSize: '42px',
            fontWeight: '400',
            color: titleColor,
            margin: '0 0 16px 0',
            letterSpacing: '-0.02em'
          }}
        >
          {sectionTitle}
        </h2>
        <p
          style={{
            fontSize: '16px',
            color: textColor,
            margin: 0,
            lineHeight: '1.6'
          }}
        >
          {sectionSubtitle}
        </p>
      </div>

      {/* Floating Cards */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'flex-end',
          gap: '28px',
          flexWrap: 'wrap',
          paddingTop: '60px' // Space for floating
        }}
      >
        {values.map((value, index) => (
          <div
            key={`${uniqueId}-value-${index}`}
            style={getCardStyle(index)}
            onMouseEnter={() => setHoveredIndex(index)}
            onMouseLeave={() => setHoveredIndex(null)}
            role="article"
            tabIndex={0}
          >
            {/* Shadow indicator below card */}
            <div
              style={{
                position: 'absolute',
                bottom: -30 - Math.abs(baseHeights[index]) + 'px',
                left: '20%',
                right: '20%',
                height: '20px',
                background: `radial-gradient(ellipse at center, ${shadowColor}20 0%, transparent 70%)`,
                transform: `scaleX(${hoveredIndex === index ? 0.8 : 1})`,
                opacity: hoveredIndex === index ? 0.5 : 0.8,
                transition: prefersReducedMotion ? 'none' : 'all 400ms ease-out',
                filter: 'blur(8px)'
              }}
              aria-hidden="true"
            />

            {/* Icon */}
            <div
              style={{
                width: '52px',
                height: '52px',
                borderRadius: '14px',
                backgroundColor: `${iconColor}08`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                marginBottom: '24px',
                fontSize: '24px',
                color: hoveredIndex === index ? accentColor : iconColor,
                transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out',
                border: `1px solid ${hoveredIndex === index ? accentColor + '30' : 'transparent'}`
              }}
            >
              {value.icon}
            </div>

            {/* Title */}
            <h3
              style={{
                fontSize: '20px',
                fontWeight: '500',
                color: titleColor,
                margin: '0 0 12px 0',
                letterSpacing: '-0.01em'
              }}
            >
              {value.title}
            </h3>

            {/* Description */}
            <p
              style={{
                fontSize: '14px',
                color: textColor,
                margin: 0,
                lineHeight: '1.6'
              }}
            >
              {value.description}
            </p>

            {/* Hover indicator */}
            <div
              style={{
                marginTop: '20px',
                display: 'flex',
                alignItems: 'center',
                gap: '6px',
                color: accentColor,
                fontSize: '13px',
                fontWeight: '500',
                opacity: hoveredIndex === index ? 1 : 0,
                transform: `translateY(${hoveredIndex === index ? 0 : 8}px)`,
                transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
              }}
            >
              Explore
              <span>→</span>
            </div>

            {/* Corner accent */}
            <div
              style={{
                position: 'absolute',
                top: '16px',
                right: '16px',
                width: '8px',
                height: '8px',
                borderRadius: '50%',
                backgroundColor: hoveredIndex === index ? accentColor : `${iconColor}30`,
                transition: prefersReducedMotion ? 'none' : 'background-color 300ms ease-out'
              }}
            />
          </div>
        ))}
      </div>

      {/* Bottom decorative element */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          marginTop: '80px',
          gap: '12px'
        }}
      >
        {values.map((_, index) => (
          <div
            key={`${uniqueId}-indicator-${index}`}
            style={{
              width: hoveredIndex === index ? '24px' : '8px',
              height: '8px',
              borderRadius: '4px',
              backgroundColor: hoveredIndex === index ? accentColor : `${iconColor}30`,
              transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out'
            }}
          />
        ))}
      </div>
    </div>
  );
}

