pricing-liquidcards:
const MANIFEST = {
  "type": "Pricing.LiquidCards",
  "description": "Award-winning liquid pricing cards with magnetic pull, particle bursts, 3D flip reveals, and smooth value animations",
  "editorElement": {
    "selector": ".liquid-pricing",
    "displayName": "Liquid Pricing Cards",
    "archetype": "container",
    "data": {
      "plans": {
        "dataType": "text",
        "displayName": "Plans (Name|Price|Period|Features|Popular)",
        "defaultValue": "Starter|29|month|5 Projects;10GB Storage;Email Support;Basic Analytics;Community Access|false,Professional|79|month|Unlimited Projects;100GB Storage;Priority Support;Advanced Analytics;Custom Domain;API Access|true,Enterprise|199|month|Everything in Pro;1TB Storage;24/7 Support;Dedicated Manager;Custom Integration;SLA Guarantee|false",
        "group": "Content"
      },
      "enableLiquidMorph": {
        "dataType": "booleanValue",
        "displayName": "Liquid Morphing",
        "defaultValue": true,
        "group": "Animation"
      },
      "enableMagneticPull": {
        "dataType": "booleanValue",
        "displayName": "Magnetic Pull",
        "defaultValue": true,
        "group": "Animation"
      },
      "enableParticleBurst": {
        "dataType": "booleanValue",
        "displayName": "Particle Burst on Click",
        "defaultValue": true,
        "group": "Animation"
      },
      "enable3DFlip": {
        "dataType": "booleanValue",
        "displayName": "3D Feature Flip",
        "defaultValue": true,
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#0A0A0A",
        "group": "Colors"
      },
      "cardBackground": {
        "dataType": "color",
        "displayName": "Card Background",
        "defaultValue": "#1A1A1A",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#E5E5E5",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "popularColor": {
        "dataType": "color",
        "displayName": "Popular Badge Color",
        "defaultValue": "#00FF88",
        "group": "Colors"
      },
      "fontSize": {
        "dataType": "number",
        "displayName": "Font Size (px)",
        "defaultValue": 14,
        "group": "Typography"
      },
      "fontWeight": {
        "dataType": "select",
        "displayName": "Font Weight",
        "defaultValue": "400",
        "options": ["300", "400", "500"],
        "group": "Typography"
      }
    }
  }
};

function Component({ config = {} }) {
  const [hoveredCard, setHoveredCard] = React.useState(null);
  const [expandedFeatures, setExpandedFeatures] = React.useState(new Set());
  const [selectedCard, setSelectedCard] = React.useState(null);
  const [particles, setParticles] = React.useState([]);
  const [mousePos, setMousePos] = React.useState({ x: 0, y: 0 });
  const [cardPositions, setCardPositions] = React.useState({});
  const [animatingPrice, setAnimatingPrice] = React.useState({});
  const cardRefs = React.useRef([]);

  const plans = (config?.plans || MANIFEST.editorElement.data.plans.defaultValue).split(',').map(plan => {
    const [name, price, period, featuresStr, popular] = plan.split('|');
    return {
      name: name?.trim(),
      price: parseInt(price?.trim() || '0'),
      period: period?.trim(),
      features: featuresStr ? featuresStr.split(';').map(f => f.trim()) : [],
      popular: popular?.trim() === 'true'
    };
  });

  const enableLiquidMorph = config?.enableLiquidMorph !== false;
  const enableMagneticPull = config?.enableMagneticPull !== false;
  const enableParticleBurst = config?.enableParticleBurst !== false;
  const enable3DFlip = config?.enable3DFlip !== false;
  const backgroundColor = config?.backgroundColor || '#0A0A0A';
  const cardBackground = config?.cardBackground || '#1A1A1A';
  const textColor = config?.textColor || '#E5E5E5';
  const accentColor = config?.accentColor || '#FFFFFF';
  const popularColor = config?.popularColor || '#00FF88';
  const fontSize = parseInt(config?.fontSize || '14');
  const fontWeight = config?.fontWeight || '400';

  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  const hexToRgba = (hex, alpha) => {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  };

  // Magnetic pull effect
  React.useEffect(() => {
    if (!enableMagneticPull || prefersReducedMotion) return;

    const handleMouseMove = (e) => {
      setMousePos({ x: e.clientX, y: e.clientY });

      cardRefs.current.forEach((card, index) => {
        if (!card) return;

        const rect = card.getBoundingClientRect();
        const cardCenterX = rect.left + rect.width / 2;
        const cardCenterY = rect.top + rect.height / 2;

        const distance = Math.sqrt(
          Math.pow(e.clientX - cardCenterX, 2) + 
          Math.pow(e.clientY - cardCenterY, 2)
        );

        if (distance < 300) {
          const intensity = 1 - (distance / 300);
          const pullX = (e.clientX - cardCenterX) * 0.08 * intensity;
          const pullY = (e.clientY - cardCenterY) * 0.08 * intensity;

          setCardPositions(prev => ({
            ...prev,
            [index]: { x: pullX, y: pullY }
          }));
        } else {
          setCardPositions(prev => ({
            ...prev,
            [index]: { x: 0, y: 0 }
          }));
        }
      });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [enableMagneticPull, prefersReducedMotion]);

  // Particle burst
  const createParticleBurst = (x, y, cardIndex) => {
    if (!enableParticleBurst || prefersReducedMotion) return;

    const newParticles = Array.from({ length: 20 }, (_, i) => ({
      id: Date.now() + i,
      x,
      y,
      angle: (Math.PI * 2 * i) / 20,
      velocity: 2 + Math.random() * 3,
      cardIndex
    }));

    setParticles(prev => [...prev, ...newParticles]);

    setTimeout(() => {
      setParticles(prev => prev.filter(p => !newParticles.includes(p)));
    }, 1000);
  };

  // Price animation
  const animatePrice = (cardIndex, targetPrice) => {
    if (prefersReducedMotion) return;

    const startPrice = animatingPrice[cardIndex] || 0;
    const duration = 1000;
    const startTime = Date.now();

    const animate = () => {
      const now = Date.now();
      const progress = Math.min((now - startTime) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3); // easeOut cubic

      const currentPrice = Math.floor(startPrice + (targetPrice - startPrice) * eased);

      setAnimatingPrice(prev => ({
        ...prev,
        [cardIndex]: currentPrice
      }));

      if (progress < 1) {
        requestAnimationFrame(animate);
      }
    };

    requestAnimationFrame(animate);
  };

  React.useEffect(() => {
    plans.forEach((plan, index) => {
      if (animatingPrice[index] !== plan.price) {
        animatePrice(index, plan.price);
      }
    });
  }, []);

  const handleCardClick = (e, cardIndex) => {
    setSelectedCard(cardIndex);

    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    createParticleBurst(x, y, cardIndex);
  };

  return (
    <div style={{
      backgroundColor,
      minHeight: '100vh',
      padding: '6rem 2rem',
      position: 'relative',
      overflow: 'hidden',
    }}>
      {/* Ambient background glow */}
      <div style={{
        position: 'absolute',
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
        width: '800px',
        height: '800px',
        background: `radial-gradient(circle, ${hexToRgba(accentColor, 0.03)} 0%, transparent 70%)`,
        pointerEvents: 'none',
      }} />

      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))',
        gap: '2rem',
        maxWidth: '1200px',
        margin: '0 auto',
        position: 'relative',
        zIndex: 1,
      }}>
        {plans.map((plan, index) => {
          const isHovered = hoveredCard === index;
          const isSelected = selectedCard === index;
          const isExpanded = expandedFeatures.has(index);
          const position = cardPositions[index] || { x: 0, y: 0 };
          const displayPrice = animatingPrice[index] || plan.price;

          const cardParticles = particles.filter(p => p.cardIndex === index);

          return (
            <div
              key={index}
              ref={el => cardRefs.current[index] = el}
              onClick={(e) => handleCardClick(e, index)}
              onMouseEnter={() => setHoveredCard(index)}
              onMouseLeave={() => setHoveredCard(null)}
              style={{
                position: 'relative',
                padding: '2.5rem 2rem',
                borderRadius: enableLiquidMorph && isHovered ? '32px' : '20px',
                backdropFilter: prefersReducedMotion ? 'none' : 'blur(40px) saturate(180%)',
                WebkitBackdropFilter: prefersReducedMotion ? 'none' : 'blur(40px) saturate(180%)',
                backgroundColor: hexToRgba(cardBackground, plan.popular ? 0.7 : 0.5),
                border: `1px solid ${hexToRgba(plan.popular ? popularColor : textColor, isHovered ? 0.3 : 0.1)}`,
                cursor: 'pointer',
                overflow: 'visible',
                perspective: '1000px',
                transformStyle: 'preserve-3d',
                transform: prefersReducedMotion ? 'none' : `
                  translate(${position.x}px, ${position.y}px)
                  scale(${isHovered ? 1.05 : isSelected ? 1.02 : 1})
                  ${plan.popular && !isHovered ? 'translateY(-10px)' : ''}
                `,
                transition: prefersReducedMotion ? 'none' : `
                  all 0.8s cubic-bezier(0.34, 1.56, 0.64, 1),
                  border-radius 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)
                `,
                boxShadow: isHovered
                  ? `
                    0 30px 80px ${hexToRgba(plan.popular ? popularColor : accentColor, 0.2)},
                    0 0 60px ${hexToRgba(plan.popular ? popularColor : accentColor, 0.1)},
                    inset 0 1px 0 ${hexToRgba('#FFFFFF', 0.15)}
                  `
                  : plan.popular
                    ? `0 20px 40px ${hexToRgba(popularColor, 0.15)}`
                    : `0 10px 30px ${hexToRgba('#000000', 0.3)}`,
                willChange: 'transform',
              }}
            >
              {/* Particles */}
              {cardParticles.map(particle => (
                <div
                  key={particle.id}
                  style={{
                    position: 'absolute',
                    left: particle.x,
                    top: particle.y,
                    width: '4px',
                    height: '4px',
                    borderRadius: '50%',
                    backgroundColor: plan.popular ? popularColor : accentColor,
                    transform: `translate(${Math.cos(particle.angle) * particle.velocity * 50}px, ${Math.sin(particle.angle) * particle.velocity * 50}px)`,
                    opacity: 0,
                    animation: prefersReducedMotion ? 'none' : 'particleFade 1s ease-out',
                    pointerEvents: 'none',
                  }}
                />
              ))}

              {/* Popular badge */}
              {plan.popular && (
                <div style={{
                  position: 'absolute',
                  top: '-12px',
                  left: '50%',
                  transform: 'translateX(-50%)',
                  padding: '0.5rem 1.5rem',
                  background: `linear-gradient(135deg, ${popularColor} 0%, ${hexToRgba(popularColor, 0.8)} 100%)`,
                  borderRadius: '20px',
                  fontSize: '11px',
                  fontWeight: '600',
                  color: '#000000',
                  textTransform: 'uppercase',
                  letterSpacing: '0.1em',
                  boxShadow: `0 4px 20px ${hexToRgba(popularColor, 0.4)}`,
                  animation: prefersReducedMotion ? 'none' : 'pulse 2s ease-in-out infinite',
                }}>
                  Most Popular
                </div>
              )}

              {/* Liquid blob background */}
              {enableLiquidMorph && isHovered && (
                <div style={{
                  position: 'absolute',
                  inset: '-20px',
                  background: `radial-gradient(circle at ${mousePos.x}px ${mousePos.y}px, ${hexToRgba(plan.popular ? popularColor : accentColor, 0.1)} 0%, transparent 60%)`,
                  borderRadius: '50%',
                  filter: 'blur(40px)',
                  pointerEvents: 'none',
                  animation: prefersReducedMotion ? 'none' : 'blobMove 3s ease-in-out infinite',
                }} />
              )}

              {/* Plan name */}
              <h3 style={{
                fontSize: '24px',
                fontWeight: '500',
                color: textColor,
                marginBottom: '1rem',
                letterSpacing: '-0.02em',
                transform: prefersReducedMotion ? 'none' : (isHovered ? 'translateX(4px)' : 'translateX(0)'),
                transition: prefersReducedMotion ? 'none' : 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)',
              }}>
                {plan.name}
              </h3>

              {/* Price with animation */}
              <div style={{
                fontSize: '56px',
                fontWeight: '300',
                color: plan.popular ? popularColor : accentColor,
                marginBottom: '0.5rem',
                letterSpacing: '-0.03em',
                transform: prefersReducedMotion ? 'none' : (isHovered ? 'scale(1.05)' : 'scale(1)'),
                transition: prefersReducedMotion ? 'none' : 'transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)',
                transformOrigin: 'left center',
              }}>
                ${displayPrice}
                <span style={{
                  fontSize: '16px',
                  color: hexToRgba(textColor, 0.5),
                  fontWeight: '400',
                  marginLeft: '0.5rem',
                }}>
                  /{plan.period}
                </span>
              </div>

              {/* Features list */}
              <div style={{
                marginTop: '2rem',
                marginBottom: '2rem',
              }}>
                {plan.features.slice(0, isExpanded ? plan.features.length : 4).map((feature, i) => (
                  <div
                    key={i}
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: '0.75rem',
                      padding: '0.75rem 0',
                      fontSize: `${fontSize}px`,
                      fontWeight,
                      color: hexToRgba(textColor, 0.8),
                      borderBottom: i < (isExpanded ? plan.features.length - 1 : 3) ? `1px solid ${hexToRgba(textColor, 0.05)}` : 'none',
                      opacity: prefersReducedMotion ? 1 : (i < 4 ? 1 : (isExpanded ? 1 : 0)),
                      maxHeight: i < 4 ? '100px' : (isExpanded ? '100px' : '0'),
                      overflow: 'hidden',
                      transform: prefersReducedMotion ? 'none' : (enable3DFlip && isExpanded && i >= 4 ? 'rotateX(0deg)' : (i >= 4 ? 'rotateX(-90deg)' : 'none')),
                      transformOrigin: 'top',
                      transition: prefersReducedMotion ? 'none' : `all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) ${i * 0.05}s`,
                    }}
                  >
                    <span style={{
                      width: '6px',
                      height: '6px',
                      borderRadius: '50%',
                      backgroundColor: plan.popular ? popularColor : accentColor,
                      flexShrink: 0,
                    }} />
                    {feature}
                  </div>
                ))}

                {plan.features.length > 4 && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setExpandedFeatures(prev => {
                        const newSet = new Set(prev);
                        if (newSet.has(index)) newSet.delete(index);
                        else newSet.add(index);
                        return newSet;
                      });
                    }}
                    style={{
                      marginTop: '1rem',
                      fontSize: `${fontSize - 2}px`,
                      color: plan.popular ? popularColor : accentColor,
                      background: 'none',
                      border: 'none',
                      cursor: 'pointer',
                      padding: 0,
                      opacity: 0.7,
                      transition: 'opacity 0.3s ease',
                    }}
                    onMouseEnter={(e) => e.currentTarget.style.opacity = '1'}
                    onMouseLeave={(e) => e.currentTarget.style.opacity = '0.7'}
                  >
                    {isExpanded ? '− Show less' : `+ ${plan.features.length - 4} more features`}
                  </button>
                )}
              </div>

              {/* CTA Button */}
              <button style={{
                width: '100%',
                padding: isHovered ? '1rem' : '0.875rem',
                background: plan.popular 
                  ? `linear-gradient(135deg, ${popularColor} 0%, ${hexToRgba(popularColor, 0.8)} 100%)`
                  : hexToRgba(accentColor, isHovered ? 0.15 : 0.08),
                color: plan.popular ? '#000000' : (isHovered ? accentColor : textColor),
                border: plan.popular ? 'none' : `1px solid ${hexToRgba(accentColor, 0.2)}`,
                borderRadius: isHovered ? '16px' : '12px',
                fontSize: `${fontSize}px`,
                fontWeight: '500',
                cursor: 'pointer',
                transition: prefersReducedMotion ? 'none' : 'all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)',
                textTransform: 'uppercase',
                letterSpacing: '0.1em',
                boxShadow: isHovered && plan.popular ? `0 8px 30px ${hexToRgba(popularColor, 0.4)}` : 'none',
                transform: prefersReducedMotion ? 'none' : (isHovered ? 'translateY(-2px)' : 'translateY(0)'),
              }}>
                Get Started
              </button>
            </div>
          );
        })}
      </div>

      <style>{`
        @keyframes particleFade {
          0% { opacity: 1; transform: scale(1); }
          100% { opacity: 0; transform: scale(0); }
        }

        @keyframes pulse {
          0%, 100% { transform: translateX(-50%) scale(1); }
          50% { transform: translateX(-50%) scale(1.05); }
        }

        @keyframes blobMove {
          0%, 100% { border-radius: 50% 60% 55% 65%; }
          25% { border-radius: 60% 50% 65% 55%; }
          50% { border-radius: 55% 65% 50% 60%; }
          75% { border-radius: 65% 55% 60% 50%; }
        }
      `}</style>
    </div>
  );
}

