        "displayName": "Accent Color",
        "defaultValue": "#FFE600",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const cardRef = React.useRef(null);
  const [rotation, setRotation] = React.useState({ x: 0, y: 0 });
  const [isHovered, setIsHovered] = React.useState(false);

  // Safe Config
  const backImg = config?.backImage || '';
  const midImg = config?.midImage || '';
  const title = config?.title || 'TITLE';
  const accent = config?.accentColor || '#FFFFFF';

  // Mouse Tilt Logic
  const handleMouseMove = (e) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const centerX = rect.width / 2;
    const centerY = rect.height / 2;

    const rotateY = ((x - centerX) / centerX) * 15; // Max 15deg
    const rotateX = ((centerY - y) / centerY) * 15; // Invert Y for correct tilt

    setRotation({ x: rotateX, y: rotateY });
  };

  const handleReset = () => {
    setIsHovered(false);
    setRotation({ x: 0, y: 0 });
  };

  return (
    <div
      style={{
        width: '100%',
        height: '100%',
        minHeight: '500px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: '#F5F5F5',
        perspective: '1200px' // Essential for 3D
      }}
    >
      <div
        ref={cardRef}
        onMouseEnter={() => setIsHovered(true)}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleReset}
        style={{
          width: '300px',
          height: '450px',
          position: 'relative',
          transformStyle: 'preserve-3d',
          transform: `rotateX(${rotation.x}deg) rotateY(${rotation.y}deg)`,
          transition: isHovered ? 'transform 0.1s linear' : 'transform 0.5s ease-out',
          cursor: 'pointer'
        }}
      >
        {/* Layer 1: Background Base */}
        <div style={{
          position: 'absolute',
          top: 0, left: 0,
          width: '100%', height: '100%',
          borderRadius: '16px',
          backgroundImage: `url(${backImg})`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          boxShadow: '0 20px 40px rgba(0,0,0,0.2)',
          transform: isHovered ? 'translateZ(0px)' : 'translateZ(0px)',
          transition: 'transform 0.4s ease-out'
        }}>
          <div style={{ 
            position: 'absolute', inset: 0, 
            backgroundColor: 'rgba(0,0,0,0.3)', 
            borderRadius: '16px' 
          }} />
        </div>

        {/* Layer 2: Subject (Floats higher) */}
        <div style={{
          position: 'absolute',
          top: '50px', left: '25px',
          width: '250px', height: '250px',
          backgroundImage: `url(${midImg})`,
          backgroundSize: 'contain',
          backgroundRepeat: 'no-repeat',
          backgroundPosition: 'center',
          transform: isHovered ? 'translateZ(60px) scale(1.1)' : 'translateZ(0px)',
          transition: 'transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)',
          pointerEvents: 'none',
          filter: 'drop-shadow(0 10px 20px rgba(0,0,0,0.3))'
        }} />

        {/* Layer 3: Typography & UI (Highest) */}
        <div style={{
          position: 'absolute',
          bottom: '40px', left: '30px',
          transform: isHovered ? 'translateZ(90px)' : 'translateZ(0px)',
          transition: 'transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)',
          pointerEvents: 'none'
        }}>
          <div style={{
            color: accent,
            fontSize: '12px',
            fontWeight: '700',
            letterSpacing: '2px',
            textTransform: 'uppercase',
            marginBottom: '8px'
          }}>
            Collection
          </div>
          <h2 style={{
            margin: 0,
            color: '#FFF',
            fontSize: '32px',
            fontWeight: '800',
            lineHeight: 1,
            textShadow: '0 4px 10px rgba(0,0,0,0.3)'
          }}>
            {title}
          </h2>
        </div>

        {/* Layer 4: Border Frame (Optional decorative) */}
        <div style={{
          position: 'absolute',
          top: '20px', left: '20px', right: '20px', bottom: '20px',
          border: `1px solid ${accent}`,
          opacity: isHovered ? 0.5 : 0,
          borderRadius: '12px',
          transform: isHovered ? 'translateZ(30px)' : 'translateZ(0px)',
          transition: 'all 0.4s ease-out',
          pointerEvents: 'none'
        }} />

      </div>
    </div>
  );
}

