function Component({ config = {} }) {
  // Safe config access with fallbacks
  const productTitle = config?.productTitle || 'Premium Product';
  const productPrice = config?.productPrice || '$99.00';
  const productDescription = config?.productDescription || 'High-quality craftsmanship';
  const imageUrl = config?.imageUrl || 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=800';
  const buttonText = config?.buttonText || 'View Details';
  const showButton = config?.showButton !== false;

  // Layout
  const cardWidth = parseInt(config?.cardWidth || '400');
  const cardPadding = parseInt(config?.cardPadding || '24');
  const imageHeight = parseInt(config?.imageHeight || '300');

  // Title typography (11 properties)
  const titleFontFamily = config?.titleFontFamily || 'Inter';
  const titleFontSize = parseInt(config?.titleFontSize || '24');
  const titleFontWeight = config?.titleFontWeight || '600';
  const titleFontStyle = config?.titleFontStyle || 'normal';
  const titleTextDecoration = config?.titleTextDecoration || 'none';
  const titleTextTransform = config?.titleTextTransform || 'none';
  const titleTextAlign = config?.titleTextAlign || 'left';
  const titleLineHeight = parseFloat(config?.titleLineHeight || '1.4');
  const titleLetterSpacing = parseFloat(config?.titleLetterSpacing || '0');
  const titleWidth = parseInt(config?.titleWidth || '100');

  // Price typography (11 properties)
  const priceFontFamily = config?.priceFontFamily || 'Inter';
  const priceFontSize = parseInt(config?.priceFontSize || '20');
  const priceFontWeight = config?.priceFontWeight || '700';
  const priceFontStyle = config?.priceFontStyle || 'normal';
  const priceTextDecoration = config?.priceTextDecoration || 'none';
  const priceTextTransform = config?.priceTextTransform || 'none';
  const priceTextAlign = config?.priceTextAlign || 'left';
  const priceLineHeight = parseFloat(config?.priceLineHeight || '1.4');
  const priceLetterSpacing = parseFloat(config?.priceLetterSpacing || '0');
  const priceWidth = parseInt(config?.priceWidth || '100');

  // Description typography (11 properties)
  const descriptionFontFamily = config?.descriptionFontFamily || 'Inter';
  const descriptionFontSize = parseInt(config?.descriptionFontSize || '14');
  const descriptionFontWeight = config?.descriptionFontWeight || '400';
  const descriptionFontStyle = config?.descriptionFontStyle || 'normal';
  const descriptionTextDecoration = config?.descriptionTextDecoration || 'none';
  const descriptionTextTransform = config?.descriptionTextTransform || 'none';
  const descriptionTextAlign = config?.descriptionTextAlign || 'left';
  const descriptionLineHeight = parseFloat(config?.descriptionLineHeight || '1.6');
  const descriptionLetterSpacing = parseFloat(config?.descriptionLetterSpacing || '0');
  const descriptionWidth = parseInt(config?.descriptionWidth || '100');

  // Button typography (11 properties)
  const buttonFontFamily = config?.buttonFontFamily || 'Inter';
  const buttonFontSize = parseInt(config?.buttonFontSize || '14');
  const buttonFontWeight = config?.buttonFontWeight || '500';
  const buttonFontStyle = config?.buttonFontStyle || 'normal';
  const buttonTextDecoration = config?.buttonTextDecoration || 'none';
  const buttonTextTransform = config?.buttonTextTransform || 'none';
  const buttonTextAlign = config?.buttonTextAlign || 'center';
  const buttonLineHeight = parseFloat(config?.buttonLineHeight || '1.4');
  const buttonLetterSpacing = parseFloat(config?.buttonLetterSpacing || '0');
  const buttonWidth = parseInt(config?.buttonWidth || '100');

  // Colors
  const titleColor = config?.titleColor || '#18181B';
  const priceColor = config?.priceColor || '#3F3F46';
  const descriptionColor = config?.descriptionColor || '#71717A';
  const cardBackground = config?.cardBackground || '#FFFFFF';
  const cardBorderColor = config?.cardBorderColor || '#E4E4E7';
  const buttonBackground = config?.buttonBackground || '#18181B';
  const buttonColor = config?.buttonColor || '#FFFFFF';
  const buttonHoverBackground = config?.buttonHoverBackground || '#27272A';

  // Hover state
  const [isHovered, setIsHovered] = React.useState(false);
  const [isButtonHovered, setIsButtonHovered] = React.useState(false);

  return (
    <div
      className="product-card-container"
      style={{
        width: cardWidth + 'px',
        backgroundColor: cardBackground,
        border: '1px solid ' + cardBorderColor,
        borderRadius: '8px',
        overflow: 'hidden',
        transition: 'all 300ms ease-out',
        transform: isHovered ? 'translateY(-4px)' : 'translateY(0)',
        boxShadow: isHovered ? '0 12px 24px rgba(0,0,0,0.1)' : '0 1px 3px rgba(0,0,0,0.06)',
        cursor: 'pointer'
      }}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Product Image */}
      <div
        style={{
          width: '100%',
          height: imageHeight + 'px',
          backgroundImage: 'url(' + imageUrl + ')',
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          transition: 'transform 300ms ease-out'
        }}
      />

      {/* Content */}
      <div style={{ padding: cardPadding + 'px' }}>

        {/* Title */}
        <h3
          style={{
            fontFamily: titleFontFamily + ', sans-serif',
            fontSize: titleFontSize + 'px',
            fontWeight: titleFontWeight,
            fontStyle: titleFontStyle,
            textDecoration: titleTextDecoration,
            textTransform: titleTextTransform,
            textAlign: titleTextAlign,
            lineHeight: titleLineHeight,
            letterSpacing: titleLetterSpacing + 'em',
            color: titleColor,
            width: titleWidth + '%',
            margin: '0 0 12px 0'
          }}
        >
          {productTitle}
        </h3>

        {/* Price */}
        <div
          style={{
            fontFamily: priceFontFamily + ', sans-serif',
            fontSize: priceFontSize + 'px',
            fontWeight: priceFontWeight,
            fontStyle: priceFontStyle,
            textDecoration: priceTextDecoration,
            textTransform: priceTextTransform,
            textAlign: priceTextAlign,
            lineHeight: priceLineHeight,
            letterSpacing: priceLetterSpacing + 'em',
            color: priceColor,
            width: priceWidth + '%',
            margin: '0 0 16px 0'
          }}
        >
          {productPrice}
        </div>

        {/* Description */}
        <p
          style={{
            fontFamily: descriptionFontFamily + ', sans-serif',
            fontSize: descriptionFontSize + 'px',
            fontWeight: descriptionFontWeight,
            fontStyle: descriptionFontStyle,
            textDecoration: descriptionTextDecoration,
            textTransform: descriptionTextTransform,
            textAlign: descriptionTextAlign,
            lineHeight: descriptionLineHeight,
            letterSpacing: descriptionLetterSpacing + 'em',
            color: descriptionColor,
            width: descriptionWidth + '%',
            margin: '0 0 24px 0'
          }}
        >
          {productDescription}
        </p>

        {/* Button */}
        {showButton && (
          <button
            style={{
              fontFamily: buttonFontFamily + ', sans-serif',
              fontSize: buttonFontSize + 'px',
              fontWeight: buttonFontWeight,
              fontStyle: buttonFontStyle,
              textDecoration: buttonTextDecoration,
              textTransform: buttonTextTransform,
              textAlign: buttonTextAlign,
              lineHeight: buttonLineHeight,
              letterSpacing: buttonLetterSpacing + 'em',
              color: buttonColor,
              width: buttonWidth + '%',
              backgroundColor: isButtonHovered ? buttonHoverBackground : buttonBackground,
              border: 'none',
              borderRadius: '4px',
              padding: '12px 24px',
              cursor: 'pointer',
              transition: 'all 300ms ease-out',
              transform: isButtonHovered ? 'translateY(-2px)' : 'translateY(0)',
              boxShadow: isButtonHovered ? '0 4px 12px rgba(0,0,0,0.15)' : 'none'
            }}
            onMouseEnter={() => setIsButtonHovered(true)}
            onMouseLeave={() => setIsButtonHovered(false)}
          >
            {buttonText}
          </button>
        )}
      </div>
    </div>
  );
}

