      if (hoverTagEffect === 'scale') tagTransform = 'scale(1.1)';
      if (hoverTagEffect === 'bounce') tagTransform = 'translateY(-5px)';
      if (hoverTagEffect === 'rotate') tagTransform = 'rotate(5deg)';
      if (hoverTagEffect === 'fade-out') tagOpacity = 0;
    }

    const presetStyles = getPresetStyles();

    // Bento grid area
    const bentoGridArea = enableBento ? getBentoGridArea(card.size, index) : null;

    const cardStyle = {
      position: 'relative',
      backgroundColor: cardPreset === 'glassmorphism' ? presetStyles.background : cardBackground,
      border: presetStyles.border || ('1px solid ' + cardBorderColor),
      borderRadius: cardBorderRadius + 'px',
      overflow: 'hidden',
      transition: `all ${transitionDuration}ms ${transitionEasing}, opacity ${entranceDuration}ms ${transitionEasing} ${index * entranceDelay}ms, transform ${entranceDuration}ms ${transitionEasing} ${index * entranceDelay}ms`,
      transform: entranceAnimation !== 'none' ? (isVisible ? cardTransform : `${cardTransform} ${entranceTransform}`) : cardTransform,
      boxShadow: presetStyles.boxShadow !== undefined ? presetStyles.boxShadow : cardShadow,
      backdropFilter: presetStyles.backdropFilter,
      cursor: 'pointer',
      opacity: entranceOpacity,
      gridArea: bentoGridArea || 'auto'
    };

    if (displayMode === 'carousel') {
      cardStyle.flex = `0 0 ${carouselCardWidth}px`;
      cardStyle.minWidth = carouselCardWidth + 'px';
    }

    // Determine if split layout
    const isSplitLayout = cardLayout !== 'overlay';
    const isHorizontalSplit = cardLayout === 'split-left' || cardLayout === 'split-right';
    const isVerticalSplit = cardLayout === 'split-top' || cardLayout === 'split-bottom';

    return (
      <div
        key={index}
        data-card-index={index}
        style={cardStyle}
        onMouseEnter={() => setHoveredCard(index)}
        onMouseLeave={() => setHoveredCard(null)}
      >
        {/* Overlay Layout */}
        {!isSplitLayout && (
          <>
            {/* Image Container */}
            <div style={{
              position: 'relative',
              aspectRatio: cardAspectRatio.replace(':', '/'),
              overflow: 'hidden'
            }}>
              {/* Image */}
              <div style={{
                width: '100%',
                height: '100%',
                backgroundImage: currentImage ? `url(${currentImage})` : 'none',
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                transition: `all ${transitionDuration}ms ${transitionEasing}`,
                transform: imageTransform,
                filter: imageFilter
              }} />

              {/* Pattern Layer */}
              {patternType !== 'none' && (
                <div style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%',
                  backgroundImage: `url('data:image/svg+xml;utf8,${encodeURIComponent(getPatternSVG())}')`,
                  backgroundRepeat: 'repeat',
                  backgroundSize: patternSize === 'small' ? '20px' : (patternSize === 'large' ? '60px' : '40px'),
                  opacity: patternOpacity,
                  clipPath: getPatternClipPath(),
                  pointerEvents: 'none',
                  zIndex: 1
                }} />
              )}

              {/* Overlay */}
              <div style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                background: overlayType === 'gradient' 
                  ? `linear-gradient(180deg, ${overlayColor} 0%, ${overlayGradientColor} 100%)`
                  : overlayColor,
                opacity: overlayHoverOpacity,
                transform: isHovered ? overlayTransform : initialOverlayTransform,
                clipPath: isHovered ? overlayClipPath : initialOverlayClipPath,
                transition: `all ${transitionDuration}ms ${transitionEasing}`,
                pointerEvents: 'none',
                zIndex: 2
              }} />

              {/* Content Overlay */}
              <div style={{
                position: 'absolute',
                top: contentValign === 'top' ? '20px' : (contentValign === 'bottom' ? 'auto' : '50%'),
                bottom: contentValign === 'bottom' ? '20px' : 'auto',
                left: '50%',
                transform: contentValign === 'center' ? 'translate(-50%, -50%)' : 'translateX(-50%)',
                width: `calc(100% - ${cardPadding * 2}px)`,
                textAlign: contentAlign,
                zIndex: 3,
                display: 'flex',
                flexDirection: 'column',
                alignItems: contentAlign === 'left' ? 'flex-start' : (contentAlign === 'right' ? 'flex-end' : 'center')
              }}>
                {/* Tag */}
                {card.tag && (
                  <span style={{
                    display: 'inline-block',
                    padding: '6px 12px',
                    backgroundColor: tagBackground,
                    borderRadius: '4px',
                    marginBottom: '12px',
                    fontFamily: tagFontFamily + ', sans-serif',
                    fontSize: tagFontSize + 'px',
                    color: tagColor,
                    fontWeight: tagFontWeight,
                    fontStyle: tagFontStyle,
                    textDecoration: tagTextDecoration,
                    textTransform: tagTextTransform,
                    textAlign: tagTextAlign,
                    lineHeight: tagLineHeight,
                    letterSpacing: tagLetterSpacing + 'em',
                    transform: tagTransform,
                    opacity: tagOpacity,
                    transition: `all ${transitionDuration}ms ${transitionEasing}`
                  }}>
                    {card.tag}
                  </span>
                )}

                {/* Title */}
                {card.title && (
                  <h3 style={{
                    margin: '0 0 8px 0',
                    fontFamily: titleFontFamily + ', sans-serif',
                    fontSize: titleFontSize + 'px',
                    color: titleHoverColor,
                    fontWeight: titleFontWeight,
                    fontStyle: titleFontStyle,
                    textDecoration: titleTextDecoration,
                    textTransform: titleTextTransform,
                    textAlign: titleTextAlign,
                    lineHeight: titleLineHeight,
                    letterSpacing: titleLetterSpacing + 'em',
                    width: titleWidth + '%',
                    maxWidth: '100%',
                    transition: `all ${transitionDuration}ms ${transitionEasing}`
                  }}>
                    {card.title}
                  </h3>
                )}

                {/* Subtitle */}
                {card.subtitle && (
                  <p style={{
