                    {card.comparePrice && (
                      <div style={{
                        marginTop: '4px',
                        fontFamily: comparePriceFontFamily + ', sans-serif',
                        fontSize: comparePriceFontSize + 'px',
                        color: comparePriceColor,
                        fontWeight: comparePriceFontWeight,
                        fontStyle: comparePriceFontStyle,
                        textDecoration: comparePriceTextDecoration,
                        textTransform: comparePriceTextTransform,
                        textAlign: comparePriceTextAlign,
                        lineHeight: comparePriceLineHeight,
                        letterSpacing: comparePriceLetterSpacing + 'em',
                        width: comparePriceWidth + '%',
                        maxWidth: '100%'
                      }}>
