                  transform: isHovered && hoverButtonEffect === 'slide-up' ? 'translateY(0)' : (hoverButtonEffect === 'slide-up' ? 'translateY(10px)' : (isHovered && hoverButtonEffect === 'slide-down' ? 'translateY(0)' : (hoverButtonEffect === 'slide-down' ? 'translateY(-10px)' : 'none'))),
