                        transition: `all ${transitionDuration}ms ${transitionEasing}`
                      }}
                      onMouseEnter={() => setHoveredButton(`specs-${index}`)}
                      onMouseLeave={() => setHoveredButton(null)}
                    >
                      {specsButtonText}
                    </button>
                  )}

                  {showQuoteButton && (
                    <button
                      style={{
