            height: '100%'
          }}>
            {/* Image Side */}
            <div style={{
              position: 'relative',
              width: isHorizontalSplit ? imageSplitRatio + '%' : '100%',
              height: isVerticalSplit ? imageSplitRatio + '%' : '100%',
