              overflow: 'hidden'
            }}>
              <div style={{
                width: '100%',
                height: '100%',
                backgroundImage: currentImage ? `url(${currentImage})` : 'none',
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                transition: `all ${transitionDuration}ms ${transitionEasing}`,
                transform: imageTransform,
                filter: imageFilter
              }} />

              {/* Pattern on image */}
              {patternType !== 'none' && (
                <div style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%',
                  backgroundImage: `url('data:image/svg+xml;utf8,${encodeURIComponent(getPatternSVG())}')`,
                  backgroundRepeat: 'repeat',
                  backgroundSize: patternSize === 'small' ? '20px' : (patternSize === 'large' ? '60px' : '40px'),
                  opacity: patternOpacity,
