                  pointerEvents: 'none'
                }} />
              )}
            </div>

            {/* Content Side */}
            <div style={{
              width: isHorizontalSplit ? (100 - imageSplitRatio) + '%' : '100%',
              height: isVerticalSplit ? (100 - imageSplitRatio) + '%' : '100%',
