                  marginBottom: '12px',
                  fontFamily: tagFontFamily + ', sans-serif',
                  fontSize: tagFontSize + 'px',
                  color: tagColor,
                  fontWeight: tagFontWeight,
                  textTransform: tagTextTransform,
                  transform: tagTransform,
                  opacity: tagOpacity,
                  transition: `all ${transitionDuration}ms ${transitionEasing}`
                }}>
                  {card.tag}
                </span>
              )}

              {/* Title */}
              {card.title && (
                <h3 style={{
                  margin: '0 0 8px 0',
                  fontFamily: titleFontFamily + ', sans-serif',
                  fontSize: titleFontSize + 'px',
                  color: titleHoverColor,
                  fontWeight: titleFontWeight,
                  textTransform: titleTextTransform,
                  lineHeight: titleLineHeight,
                  letterSpacing: titleLetterSpacing + 'em',
                  transition: `all ${transitionDuration}ms ${transitionEasing}`
                }}>
                  {card.title}
                </h3>
              )}

              {/* Subtitle */}
              {card.subtitle && (
                <p style={{
                  margin: '0 0 12px 0',
                  fontFamily: subtitleFontFamily + ', sans-serif',
                  fontSize: subtitleFontSize + 'px',
                  color: subtitleColor,
                  fontWeight: subtitleFontWeight,
                  lineHeight: subtitleLineHeight
                }}>
                  {card.subtitle}
                </p>
              )}

              {/* Rating */}
              {card.rating && (
                <div style={{
                  marginBottom: '12px',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px',
                  fontFamily: ratingFontFamily + ', sans-serif',
                  fontSize: ratingFontSize + 'px',
                  color: ratingTextColor
                }}>
                  {renderStars(card.rating)}
                  <span>({card.rating})</span>
                </div>
              )}

              {/* Price */}
              {card.price && (
                <div style={{ marginBottom: '20px', width: '100%' }}>
                  <div style={{
                    fontFamily: priceFontFamily + ', sans-serif',
                    fontSize: priceFontSize + 'px',
                    color: priceColor,
                    fontWeight: priceFontWeight,
                    lineHeight: priceLineHeight
                  }}>
                    {card.price}
                  </div>
                  {card.comparePrice && (
                    <div style={{
                      marginTop: '4px',
                      fontFamily: comparePriceFontFamily + ', sans-serif',
                      fontSize: comparePriceFontSize + 'px',
                      color: comparePriceColor,
                      textDecoration: comparePriceTextDecoration
                    }}>
                      {card.comparePrice}
                    </div>
                  )}
                </div>
              )}

              {/* Buttons */}
              <div style={{
                display: 'flex',
                gap: '8px',
                flexWrap: 'wrap',
                opacity: hoverButtonEffect === 'always-visible' ? 1 : (isHovered || hoverButtonEffect === 'none' ? 1 : 0),
                transition: `all ${transitionDuration}ms ${transitionEasing}`
              }}>
                {showSpecsButton && (
                  <button
                    style={{
                      padding: '10px 20px',
                      backgroundColor: hoveredButton === `specs-${index}` ? buttonHoverBackground : buttonBackground,
                      border: 'none',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      fontFamily: buttonFontFamily + ', sans-serif',
                      fontSize: buttonFontSize + 'px',
                      color: buttonColor,
                      fontWeight: buttonFontWeight,
                      transition: `all ${transitionDuration}ms ${transitionEasing}`
                    }}
                    onMouseEnter={() => setHoveredButton(`specs-${index}`)}
                    onMouseLeave={() => setHoveredButton(null)}
                  >
                    {specsButtonText}
                  </button>
                )}

                {showQuoteButton && (
                  <button
                    style={{
                      padding: '10px 20px',
                      backgroundColor: quoteButtonBackground,
                      border: '1px solid rgba(255,255,255,0.3)',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      fontFamily: buttonFontFamily + ', sans-serif',
                      fontSize: buttonFontSize + 'px',
                      color: '#FFFFFF',
                      fontWeight: buttonFontWeight,
                      transition: `all ${transitionDuration}ms ${transitionEasing}`
                    }}
                  >
                    {quoteButtonText}
                  </button>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    );
  };

  // Container style
  const containerStyle = {
    display: displayMode === 'carousel' ? 'flex' : 'grid',
    gap: gap + 'px',
    padding: '40px 20px',
    width: '100%',
    maxWidth: '1400px',
    margin: '0 auto'
  };

  if (displayMode === 'grid') {
    if (enableBento) {
      // Bento layout: auto-fill grid with flexible columns
      containerStyle.gridTemplateColumns = 'repeat(auto-fill, minmax(250px, 1fr))';
      containerStyle.gridAutoRows = '250px';
      containerStyle.gridAutoFlow = 'dense';
    } else {
      // Regular grid
      containerStyle.gridTemplateColumns = `repeat(${columns}, 1fr)`;
    }
  } else {
    containerStyle.overflowX = 'auto';
    containerStyle.WebkitOverflowScrolling = 'touch';
    containerStyle.scrollBehavior = 'smooth';
  }

  if (cardsData.length === 0) {
    return (
      <div style={{
        padding: '80px 20px',
        textAlign: 'center',
        color: '#71717A',
        fontFamily: 'Inter, sans-serif'
      }}>
        <p style={{ fontSize: '18px', marginBottom: '8px' }}>No cards to display</p>
        <p style={{ fontSize: '14px', opacity: 0.7 }}>Add card data in JSON format to the "Cards Data" field</p>
      </div>
    );
  }

  return (
    <div ref={containerRef} className="stp-product-card" style={containerStyle}>
      {cardsData.map((card, index) => renderCard(card, index))}
    </div>
  );
}

