              <span>צרו קשר</span>
              {getIcon('ArrowUpRight', 16)}
            </button>
          </div>

          {/* Clients Card */}
          <div
            style={{
              ...cardStyle(8),
              gridColumn: 'span 12',
              padding: '32px 40px'
            }}
            onMouseEnter={() => setHoveredCard(8)}
            onMouseLeave={() => setHoveredCard(null)}
          >
            <div style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              flexWrap: 'wrap',
              gap: '24px'
            }}>
              <div style={{
                fontSize: '12px',
                fontWeight: '500',
                letterSpacing: '0.1em',
                color: secondaryText
              }}>
                סומכים עלינו
              </div>
              <div style={{
                display: 'flex',
                gap: '40px',
                flexWrap: 'wrap'
              }}>
                {['קניונים', 'משחקיות', 'ברים', 'אולמות משחק', 'חברות הייטק', 'חברות הפקה', 'ועדי עובדים'].map((client, index) => (
                  <span
                    key={index}
                    style={{
                      fontSize: '14px',
                      color: secondaryText
                    }}
                  >
                    {client}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <footer style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '40px 8px',
          marginTop: '24px'
        }}>
          <div style={{
            fontSize: '13px',
            color: secondaryText
          }}>
            © 2024 {companyName}
          </div>
          <div style={{
            display: 'flex',
            gap: '24px'
          }}>
            <div style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              fontSize: '13px',
              color: secondaryText
            }}>
              {getIcon('Phone', 14)}
              <span>03-1234567</span>
            </div>
            <div style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              fontSize: '13px',
              color: secondaryText
            }}>
              {getIcon('MapPin', 14)}
              <span>ישראל</span>
            </div>
          </div>
        </footer>
      </div>
    </div>
  );
}

