  const darkCard = config?.darkCard || "#1D1D1F";
  const textPrimary = config?.textPrimary || "#1D1D1F";
  const textSecondary = config?.textSecondary || "#6E6E73";
  const accentBlue = config?.accentBlue || "#0071E3";
  const accentPurple = config?.accentPurple || "#A855F7";
  const accentGreen = config?.accentGreen || "#22C55E";

  const values = [
    { icon: "✨", title: "Craft", desc: "Every pixel matters", color: accentBlue },
    { icon: "🤝", title: "Collaborate", desc: "Better together", color: accentPurple },
    { icon: "🚀", title: "Ship", desc: "Done beats perfect", color: accentGreen },
    { icon: "💡", title: "Innovate", desc: "Push boundaries", color: "#F59E0B" }
  ];

  const team = [
    { name: "Andrew Wilkinson", role: "CEO", emoji: "👨‍💼" },
    { name: "Chris Baum", role: "President", emoji: "👨‍💻" },
    { name: "Sophie Kim", role: "Design Lead", emoji: "👩‍🎨" },
    { name: "Marcus Chen", role: "Engineering Lead", emoji: "🧑‍💻" }
  ];

  const services = ["Product Strategy", "UX Research", "Interface Design", "Frontend Development", "Design Systems", "Brand Identity"];

  const locations = [
    { city: "Victoria", flag: "🇨🇦" },
    { city: "San Francisco", flag: "🇺🇸" },
    { city: "London", flag: "🇬🇧" }
  ];

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisibleCards(prev => new Set([...prev, entry.target.dataset.card]));
          }
        });
      },
      { threshold: 0.1 }
    );

    const cards = document.querySelectorAll('[data-card]');
    cards.forEach(card => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  const isVisible = (card) => visibleCards.has(card);

  const cardStyle = (card, delay = 0) => ({
    backgroundColor: cardBackground,
    borderRadius: '24px',
    padding: '32px',
    opacity: isVisible(card) ? 1 : 0,
    transform: isVisible(card) ? 'translateY(0)' : 'translateY(30px)',
    transition: `opacity 0.6s ease ${delay}s, transform 0.6s ease ${delay}s, box-shadow 0.3s ease`,
    boxShadow: hoveredCard === card 
      ? '0 20px 60px rgba(0,0,0,0.12)' 
      : '0 2px 8px rgba(0,0,0,0.04)',
    cursor: 'pointer'
  });

  return (
    <div 
      className="about-bento-grid" 
      style={{
        fontFamily: "'SF Pro Display', -apple-system, BlinkMacSystemFont, sans-serif",
        backgroundColor,
        color: textPrimary,
        minHeight: '100vh',
        padding: '40px'
      }}
    >
      <style>{`
