          transition: all 0.3s ease;
        }
        .service-chip:hover {
          background: ${accentBlue}15 !important;
          color: ${accentBlue} !important;
        }
        .team-avatar {
          transition: transform 0.3s ease;
        }
        .team-avatar:hover {
          transform: scale(1.1);
        }
        .value-card {
          transition: all 0.3s ease;
        }
        .value-card:hover {
          transform: scale(1.02);
        }
      `}</style>

      <div style={{
        maxWidth: '1400px',
        margin: '0 auto'
      }}>
        {/* Header */}
        <header style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: '60px'
        }}>
          <span style={{
            fontSize: '20px',
            fontWeight: 600,
            letterSpacing: '-0.02em'
          }}>{companyName}</span>
          <nav style={{ display: 'flex', gap: '32px' }}>
            {['Work', 'Services', 'About', 'Careers'].map((item, i) => (
