              ...cardStyle('hero', 0),
              gridColumn: 'span 8',
              gridRow: 'span 3',
              display: 'flex',
              flexDirection: 'column',
              justifyContent: 'space-between',
              padding: '48px'
            }}
          >
            <div>
              <span style={{
                display: 'inline-block',
                padding: '8px 16px',
                backgroundColor: `${accentBlue}10`,
                color: accentBlue,
