                    fontSize: '15px',
                    fontWeight: 600,
                    marginBottom: '4px'
                  }}>{member.name}</h4>
                  <p style={{
                    fontSize: '13px',
                    color: textSecondary
                  }}>{member.role}</p>
                </div>
              ))}
            </div>
          </div>

          {/* CTA Card */}
          <div 
            data-card="cta"
            className="bento-card"
            onMouseEnter={() => setHoveredCard('cta')}
            onMouseLeave={() => setHoveredCard(null)}
            style={{
              ...cardStyle('cta', 0.35),
              gridColumn: 'span 12',
              gridRow: 'span 1',
              background: `linear-gradient(135deg, ${accentBlue} 0%, ${accentPurple} 100%)`,
              color: '#FFFFFF',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}
          >
            <div>
              <h3 style={{
                fontSize: '28px',
                fontWeight: 700,
                letterSpacing: '-0.02em',
                marginBottom: '8px'
              }}>Ready to build something great?</h3>
              <p style={{
                fontSize: '16px',
                opacity: 0.9
              }}>Let's talk about your next project.</p>
            </div>
            <button style={{
              padding: '16px 32px',
              backgroundColor: '#FFFFFF',
              color: accentBlue,
              border: 'none',
              borderRadius: '12px',
              fontSize: '15px',
              fontWeight: 600,
              cursor: 'pointer',
              transition: 'transform 0.3s ease'
            }}>Get in Touch</button>
          </div>
        </div>

        {/* Footer */}
        <footer style={{
          marginTop: '60px',
          padding: '32px 0',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          borderTop: `1px solid ${textPrimary}10`
        }}>
          <p style={{ fontSize: '13px', color: textSecondary }}>
            © {new Date().getFullYear()} {companyName}. All rights reserved.
          </p>
          <div style={{ display: 'flex', gap: '24px' }}>
            {['Twitter', 'LinkedIn', 'Instagram', 'Dribbble'].map((social, i) => (
              <a key={i} href="#" style={{
                fontSize: '13px',
                color: textSecondary,
                textDecoration: 'none'
              }}>{social}</a>
            ))}
          </div>
        </footer>
      </div>
    </div>
  );
}

