  const heroTitle = config?.heroTitle || "אנחנו ארקייד גיימס";
  const heroTagline = config?.heroTagline || "מביאים את עולם המשחקים לישראל";
  const storyTitle = config?.storyTitle || "הסיפור";
  const storyText = config?.storyText || "חברת ארקייד גיימס נוסדה בשנת 2008...";
  const missionTitle = config?.missionTitle || "המשימה";
  const missionText = config?.missionText || "כחברה מובילה בתחומה...";
  const productsTitle = config?.productsTitle || "המוצרים";
  const products = [
    config?.product1 || "מכונות משחק",
    config?.product2 || "מכונות בובות",
    config?.product3 || "מכונות ספורט",
    config?.product4 || "מכונות רכיבה",
    config?.product5 || "משחקי סימולטור",
    config?.product6 || "מתקני שעשוע"
  ];
  const experienceValue = config?.experienceValue || "20+";
  const experienceLabel = config?.experienceLabel || "שנות ניסיון בתעשייה";
  const ctaTitle = config?.ctaTitle || "בואו נעבוד ביחד";
  const ctaButton = config?.ctaButton || "צור קשר";

  const backgroundColor = config?.backgroundColor || "#E4E4E7";
  const cardColor = config?.cardColor || "#FFFFFF";
  const darkCardColor = config?.darkCardColor || "#18181B";
  const primaryText = config?.primaryText || "#18181B";
  const lightText = config?.lightText || "#FFFFFF";
  const mutedText = config?.mutedText || "#71717A";

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisible(prev => ({ ...prev, [entry.target.id]: true }));
          }
        });
      },
      { threshold: 0.2 }
    );

    Object.values(refs.current).forEach(ref => {
      if (ref) observer.observe(ref);
    });

    return () => observer.disconnect();
  }, []);

  const cardBaseStyle = {
    borderRadius: '24px',
    padding: '60px',
    boxShadow: '0 10px 40px rgba(0,0,0,0.08)',
    transition: 'transform 0.6s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.6s ease'
  };

  return (
    <div className="about-cardstack" style={{
      fontFamily: '"Noto Sans Hebrew", "Noto Sans", sans-serif',
      backgroundColor,
      color: primaryText,
      minHeight: '100vh',
      direction: 'rtl',
      padding: '40px'
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Hebrew:wght@300;400;500&display=swap');

        @keyframes cardIn {
          from {
            opacity: 0;
            transform: translateY(60px) scale(0.98);
          }
          to {
            opacity: 1;
            transform: translateY(0) scale(1);
          }
        }

        .card-animate {
          animation: cardIn 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards;
          opacity: 0;
        }

        .stack-card {
          position: relative;
        }

        .stack-card:hover {
          transform: translateY(-8px);
        }
      `}</style>

      {/* Header */}
      <header style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        padding: '20px 40px',
        marginBottom: '40px'
      }}>
        <span style={{
          fontSize: '15px',
          fontWeight: 500,
          color: primaryText
        }}>
          {companyName}
        </span>
        <span style={{
          fontSize: '13px',
          fontWeight: 400,
          color: mutedText
        }}>
          אודות
        </span>
      </header>

      <div style={{
        maxWidth: '1200px',
        margin: '0 auto',
        display: 'flex',
        flexDirection: 'column',
        gap: '24px'
      }}>
        {/* Hero Card */}
        <div
          id="hero"
          ref={el => refs.current.hero = el}
          className={`stack-card ${visible.hero ? 'card-animate' : ''}`}
          style={{
            ...cardBaseStyle,
            backgroundColor: darkCardColor,
            color: lightText,
            minHeight: '400px',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'flex-end'
          }}
        >
          <p style={{
            fontSize: '14px',
            fontWeight: 400,
            color: 'rgba(255,255,255,0.5)',
            marginBottom: '20px',
            letterSpacing: '0.1em'
          }}>
            אודות
          </p>
          <h1 style={{
            fontSize: 'clamp(36px, 5vw, 60px)',
            fontWeight: 300,
            lineHeight: 1.1,
            marginBottom: '20px'
          }}>
            {heroTitle}
          </h1>
          <p style={{
            fontSize: '20px',
            fontWeight: 400,
            color: 'rgba(255,255,255,0.7)',
            maxWidth: '600px'
          }}>
            {heroTagline}
          </p>
        </div>

        {/* Story & Experience Row */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: '2fr 1fr',
          gap: '24px'
        }}>
          {/* Story Card */}
          <div
            id="story"
            ref={el => refs.current.story = el}
            className={`stack-card ${visible.story ? 'card-animate' : ''}`}
            style={{
              ...cardBaseStyle,
              backgroundColor: cardColor,
              animationDelay: '0.1s'
            }}
          >
            <h2 style={{
              fontSize: '13px',
              fontWeight: 500,
              letterSpacing: '0.1em',
              color: mutedText,
              marginBottom: '30px'
            }}>
              {storyTitle}
            </h2>
            <p style={{
              fontSize: 'clamp(18px, 2vw, 22px)',
              fontWeight: 400,
              lineHeight: 1.7
            }}>
              {storyText}
            </p>
          </div>

          {/* Experience Card */}
          <div
            id="experience"
            ref={el => refs.current.experience = el}
            className={`stack-card ${visible.experience ? 'card-animate' : ''}`}
            style={{
              ...cardBaseStyle,
              backgroundColor: cardColor,
              display: 'flex',
              flexDirection: 'column',
              justifyContent: 'center',
              alignItems: 'center',
              textAlign: 'center',
              animationDelay: '0.2s'
            }}
          >
            <p style={{
              fontSize: '72px',
              fontWeight: 300,
              lineHeight: 1,
              marginBottom: '16px'
            }}>
              {experienceValue}
            </p>
            <p style={{
              fontSize: '15px',
              fontWeight: 400,
              color: mutedText
            }}>
              {experienceLabel}
            </p>
          </div>
        </div>

        {/* Mission Card */}
        <div
          id="mission"
          ref={el => refs.current.mission = el}
          className={`stack-card ${visible.mission ? 'card-animate' : ''}`}
          style={{
            ...cardBaseStyle,
            backgroundColor: cardColor,
            animationDelay: '0.15s'
          }}
        >
          <h2 style={{
            fontSize: '13px',
            fontWeight: 500,
            letterSpacing: '0.1em',
            color: mutedText,
            marginBottom: '30px'
          }}>
            {missionTitle}
          </h2>
          <p style={{
            fontSize: 'clamp(18px, 2vw, 22px)',
            fontWeight: 400,
            lineHeight: 1.7,
            maxWidth: '800px'
          }}>
            {missionText}
          </p>
        </div>

        {/* Products Card */}
        <div
          id="products"
          ref={el => refs.current.products = el}
          className={`stack-card ${visible.products ? 'card-animate' : ''}`}
          style={{
            ...cardBaseStyle,
            backgroundColor: cardColor,
            animationDelay: '0.2s'
          }}
        >
          <h2 style={{
            fontSize: '13px',
            fontWeight: 500,
            letterSpacing: '0.1em',
            color: mutedText,
            marginBottom: '40px'
          }}>
            {productsTitle}
          </h2>
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
            gap: '20px'
          }}>
            {products.map((product, index) => (
              <div key={index} style={{
                padding: '24px',
                backgroundColor: backgroundColor,
                borderRadius: '12px',
                fontSize: '16px',
                fontWeight: 400,
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                transition: 'background-color 0.3s ease'
              }}>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke={primaryText} strokeWidth="1.5">
                  <rect x="3" y="3" width="18" height="18" rx="2" />
                  <path d="M12 8v8M8 12h8" />
                </svg>
                {product}
              </div>
            ))}
          </div>
        </div>

        {/* CTA Card */}
        <div
          id="cta"
          ref={el => refs.current.cta = el}
          className={`stack-card ${visible.cta ? 'card-animate' : ''}`}
          style={{
            ...cardBaseStyle,
            backgroundColor: darkCardColor,
            color: lightText,
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            animationDelay: '0.25s'
          }}
        >
          <h2 style={{
            fontSize: 'clamp(24px, 3vw, 36px)',
            fontWeight: 400
          }}>
            {ctaTitle}
          </h2>
          <button style={{
            backgroundColor: lightText,
            color: darkCardColor,
            border: 'none',
            padding: '16px 40px',
            fontSize: '15px',
            fontWeight: 500,
            borderRadius: '12px',
            cursor: 'pointer',
            transition: 'transform 0.3s ease'
          }}
          onMouseEnter={e => e.target.style.transform = 'scale(1.03)'}
          onMouseLeave={e => e.target.style.transform = 'scale(1)'}
          >
            {ctaButton}
          </button>
        </div>
      </div>
    </div>
  );
}
